INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('fstandhartinger/ralph-wiggum/ralph-wiggum', 'ralph-wiggum', 'fstandhartinger', 'ralph-wiggum', 'community', 'ralph-wiggum fstandhartinger ralph-wiggum community Ralph Wiggum是一种基于规格的Autonomous AI编码工具，帮助开发者提高编码效率 Ralph Wiggumは仕様駆動開発によるAutonomous AIコーディングツールであり、開発者のコーディング効率を向上させる Ralph Wiggum은 규격 기반의 자동화 AI 코딩 도구로 개발자의 코딩 효율성을 향상 시킵니다 Ralph Wiggum es un agente de IA para desarrollo de código autónomo basado en especificaciones Ralph Wiggum est un outil d''IA pour développement de code autonome basé sur des spécifications Ralph Wiggum ist ein KI-Agent für autonomes Coden basierend auf Spezifikationen Ralph Wiggum é um agente de IA autônomo com desenvolvimento baseado em especificações. Aprenda a usar agora Ralph Wiggum - автономный ИИ агент с разработкой на основе спецификаций. Узнайте как использовать сейчас رالف وايغام هو وكيل ذكاء اصطناعي مستقل مع تطوير مدفوع بالمواصفات. تعلم كيفية استخدامه الآن Ralph Wiggum: Autonomous AI coding with spec-driven development. Point your AI agent here to get started. 如何使用Ralph Wiggum 什么是Autonomous AI编码 Ralph Wiggum替代品 Ralph Wiggum vs 其他AI工具 Ralph Wiggum安装 Ralph Wiggum设置指南 AIエージェント的应用 自动化编码的优势 Ralph Wiggum: Autonomous AI coding with spec-driven development. Point your AI agent here to get started.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('proffesor-for-testing/sentinel-api-testing/quality-metrics', 'community', 'proffesor-for-testing', 'sentinel-api-testing', 'proffesor-for-testing/sentinel-api-testing', 'quality-metrics', 0, 0, 56, '2026-03-04T13:07:01.682Z', '2026-03-04T13:24:39.514Z', '6368fc153b1626be1079ca4c5694b9276dfa9315cf481fe722e6f9fb31504671', '{"id":"proffesor-for-testing/sentinel-api-testing/quality-metrics","name":"quality-metrics","description":{"zh":"AI Agentic API Testing Platform提供自动化测试和代码质量评估","ja":"AIエージェントを活用した自動テストプラットフォーム","ko":"AI 에이전트를 활용한 자동화 테스트 플랫폼","es":"La plataforma de pruebas de API de agentes de IA ofrece pruebas automatizadas con agentes efímeros especializados para garantizar la calidad de los agentes de IA.","fr":"La plateforme de tests d''API d''agents d''IA propose des tests automatisés avec des agents éphémères spécialisés pour assurer la qualité des agents d''IA.","de":"Die KI-Agenten-API-Testplattform bietet automatisierte Tests mit spezialisierten ephemeren Agenten, um die Qualität der KI-Agenten zu gewährleisten.","pt":"A plataforma de testes de API com agentes efêmeros especializados oferece testes automatizados de alta qualidade.","ru":"Платформа для тестирования API с помощью специализированных эфемерных агентов обеспечивает автоматизированное тестирование высокого качества.","ar":"منصة اختبار واجهة برمجة التطبيقات مع وكلاء مؤقتين متخصصين توفر اختبارات自动ية عالية الجودة.","en":"AI Agentic API Testing Platform - Automated testing with specialized ephemeral agents"},"seo":{"title":{"zh":"AI智能代理质量指标 - 自动化测试平台","ja":"AIエージェントの品質メトリクス - 自動テストプラットフォーム","ko":"AI 에이전트 품질 메트릭스 - 자동화 테스트 플랫폼","es":"Herramientas de calidad para agentes de IA","fr":"Outils de qualité pour les agents d''IA","de":"Qualitätsmetriken für KI-Agenten","pt":"Ferramentas de IQ - Plataforma de Testes de API com Agent...","ru":"ИИ Агенты - Платформа для автоматизированного тестировани...","ar":"أدوات الذكاء الاصطناعي - منصة اختبار واجهة برمجة التطبيقا...","en":"quality-metrics"},"description":{"zh":"AI Agentic API Testing Platform提供自动化测试和代码质量评估","ja":"AIエージェントを活用した自動テストプラットフォーム","ko":"AI 에이전트를 활용한 자동화 테스트 플랫폼","es":"La plataforma de pruebas de API de agentes de IA ofrece pruebas automatizadas con agentes efímeros especializados para garantizar la calidad de los agentes d...","fr":"La plateforme de tests d''API d''agents d''IA propose des tests automatisés avec des agents éphémères spécialisés pour assurer la qualité des agents d''IA.","de":"Die KI-Agenten-API-Testplattform bietet automatisierte Tests mit spezialisierten ephemeren Agenten, um die Qualität der KI-Agenten zu gewährleisten.","pt":"A plataforma de testes de API com agentes efêmeros especializados oferece testes automatizados de alta qualidade.","ru":"Платформа для тестирования API с помощью специализированных эфемерных агентов обеспечивает автоматизированное тестирование высокого качества.","ar":"منصة اختبار واجهة برمجة التطبيقات مع وكلاء مؤقتين متخصصين توفر اختبارات自动ية عالية الجودة.","en":"AI Agentic API Testing Platform - Automated testing with specialized ephemeral agents"},"definition":{"en":"AI Agentic API Testing Platform - Automated testing with specialized ephemeral agents"},"features":{"zh":["自动化测试","代码质量评估","AI智能代理","API测试","开发效率提高"],"ja":["自動テスト","コード品質評価","AIエージェント","APIテスト","開発効率向上"],"ko":["자동화 테스트","코드 품질 평가","AI 에이전트","API 테스트","개발 효율성 개선"],"es":["Pruebas automatizadas de API","Agentes efímeros especializados","Integración con herramientas de desarrollo","Informes detallados de pruebas","Soporte para múltiples plataformas"],"fr":["Tests automatisés d''API","Agents éphémères spécialisés","Intégration avec des outils de développement","Rapports détaillés de tests","Support pour plusieurs plateformes"],"de":["Automatisierte API-Tests","Spezialisierte ephemere Agenten","Integration mit Entwicklungstools","Detaillierte Testberichte","Unterstützung für mehrere Plattformen"],"pt":["Testes automatizados de alta qualidade","Agentes efêmeros especializados","Plataforma de testes de API avançada","Integração com ferramentas de desenvolvimento","Relatórios detalhados de testes","Suporte a múltiplos ambientes de teste"],"ru":["Автоматизированное тестирование высокого качества","Специализированные эфемерные агенты","Продвинутая платформа для тестирования API","Интеграция с инструментами разработки","Подробные отчеты о тестировании","Поддержка нескольких тестовых сред"],"ar":["اختبارات أوتوماتيكية عالية الجودة","وكلاء مؤقتون متخصصون","منصة اختبار واجهة برمجة التطبيقات المتقدمة","التكامل مع أدوات التطوير","تقارير مفصلة عن الاختبارات","دعم لعدة بيئات الاختبار"]},"keywords":{"zh":["AI智能代理","自动化测试","代码质量评估","API测试","如何使用AI Agentic","AI Agentic替代品","AI Agentic安装"],"ja":["AIエージェント","自動テスト","コード品質評価","APIテスト","AIエージェントの使い方","AIエージェントの代替","AIエージェントのインストール"],"ko":["AI 에이전트","자동화 테스트","코드 품질 평가","API 테스트","AI 에이전트 사용 방법","AI 에이전트 대안","AI 에이전트 설치 가이드"],"es":["herramientas de calidad para agentes de IA","cómo utilizar agentes de IA","qué es un agente de IA","alternativas a agentes de IA","agentes de IA vs herramientas de automatización","instalación de agentes de IA","guía de configuración de agentes de IA"],"fr":["outils de qualité pour les agents d''IA","comment utiliser les agents d''IA","quoi est un agent d''IA","alternatives aux agents d''IA","agents d''IA vs outils d''automatisation","installation d''agents d''IA","guide de configuration des agents d''IA"],"de":["Qualitätsmetriken für KI-Agenten","wie man KI-Agenten verwendet","was ist ein KI-Agent","Alternativen zu KI-Agenten","KI-Agenten vs Automatisierungstools","Installation von KI-Agenten","Konfigurationsleitfaden für KI-Agenten"],"pt":["como usar agentes de teste","o que é plataforma de testes de API","alternativa para testes de API","guia de instalação de agentes de teste","configuração de testes de API","melhores práticas para testes de API","ferramentas de teste de API","desenvolvimento de software com testes automatizados"],"ru":["как использовать тестовые агенты","что такое платформа для тестирования API","альтернатива для тестирования API","руководство по установке тестовых агентов","настройка тестирования API","лучшие практики для тестирования API","инструменты для тестирования API","разработка программного обеспечения с автоматизированным тестированием"],"ar":["كيفية استخدام وكلاء الاختبار","ما هي منصة اختبار واجهة برمجة التطبيقات","بديل لاختبار واجهة برمجة التطبيقات","دليل تثبيت وكلاء الاختبار","إعداد اختبار واجهة برمجة التطبيقات","أفضل الممارسات لاختبار واجهة برمجة التطبيقات","أدوات اختبار واجهة برمجة التطبيقات","تطوير البرمجيات مع الاختبارات الأوتوماتيكية"]}},"owner":"proffesor-for-testing","repo":"sentinel-api-testing","repoPath":"proffesor-for-testing/sentinel-api-testing","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.682Z","topics":[],"category":"community","skillMd":{"name":"quality-metrics","description":"Measure quality effectively with actionable metrics. Use when establishing quality dashboards, defining KPIs, or evaluating test effectiveness.","tags":["metrics","dora","quality-gates","dashboards","kpis","measurement"],"bodyPreview":"# Quality Metrics\n\n<default_to_action>\nWhen measuring quality or building dashboards:\n1. MEASURE outcomes (bug escape rate, MTTD) not activities (test count)\n2. FOCUS on DORA metrics: Deployment frequency, Lead time, MTTD, MTTR, Change failure rate\n3. AVOID vanity metrics: 100% coverage means nothing if tests don''t catch bugs\n4. SET thresholds that drive behavior (quality gates block bad code)\n5. TREND over time: Direction matters more than absolute numbers\n\n**Quick Metric Selection:**\n- Speed:","body":"# Quality Metrics\n\n<default_to_action>\nWhen measuring quality or building dashboards:\n1. MEASURE outcomes (bug escape rate, MTTD) not activities (test count)\n2. FOCUS on DORA metrics: Deployment frequency, Lead time, MTTD, MTTR, Change failure rate\n3. AVOID vanity metrics: 100% coverage means nothing if tests don''t catch bugs\n4. SET thresholds that drive behavior (quality gates block bad code)\n5. TREND over time: Direction matters more than absolute numbers\n\n**Quick Metric Selection:**\n- Speed: Deployment frequency, lead time for changes\n- Stability: Change failure rate, MTTR\n- Quality: Bug escape rate, defect density, test effectiveness\n- Process: Code review time, flaky test rate\n\n**Critical Success Factors:**\n- Metrics without action are theater\n- What you measure is what you optimize\n- Trends matter more than snapshots\n</default_to_action>\n\n## Quick Reference Card\n\n### When to Use\n- Building quality dashboards\n- Defining quality gates\n- Evaluating testing effectiveness\n- Justifying quality investments\n\n### Meaningful vs Vanity Metrics\n| ✅ Meaningful | ❌ Vanity |\n|--------------|-----------|\n| Bug escape rate | Test case count |\n| MTTD (detection) | Lines of test code |\n| MTTR (recovery) | Test executions |\n| Change failure rate | Coverage % (alone) |\n| Lead time for changes | Requirements traced |\n\n### DORA Metrics\n| Metric | Elite | High | Medium | Low |\n|--------|-------|------|--------|-----|\n| Deploy Frequency | On-demand | Weekly | Monthly | Yearly |\n| Lead Time | < 1 hour | < 1 week | < 1 month | > 6 months |\n| Change Failure Rate | < 5% | < 15% | < 30% | > 45% |\n| MTTR | < 1 hour | < 1 day | < 1 week | > 1 month |\n\n### Quality Gate Thresholds\n| Metric | Blocking Threshold | Warning |\n|--------|-------------------|---------|\n| Test pass rate | 100% | - |\n| Critical coverage | > 80% | > 70% |\n| Security critical | 0 | - |\n| Performance p95 | < 200ms | < 500ms |\n| Flaky tests | < 2% | < 5% |\n\n---\n\n## Core Metrics\n\n### Bug Escape Rate\n```\nBug Escape Rate = (Production Bugs / Total Bugs Found) × 100\n\nTarget: < 10% (90% caught before production)\n```\n\n### Test Effectiveness\n```\nTest Effectiveness = (Bugs Found by Tests / Total Bugs) × 100\n\nTarget: > 70%\n```\n\n### Defect Density\n```\nDefect Density = Defects / KLOC\n\nGood: < 1 defect per KLOC\n```\n\n### Mean Time to Detect (MTTD)\n```\nMTTD = Time(Bug Reported) - Time(Bug Introduced)\n\nTarget: < 1 day for critical, < 1 week for others\n```\n\n---\n\n## Dashboard Design\n\n```typescript\n// Agent generates quality dashboard\nawait Task(\"Generate Dashboard\", {\n  metrics: {\n    delivery: [''deployment-frequency'', ''lead-time'', ''change-failure-rate''],\n    quality: [''bug-escape-rate'', ''test-effectiveness'', ''defect-density''],\n    stability: [''mttd'', ''mttr'', ''availability''],\n    process: [''code-review-time'', ''flaky-test-rate'', ''coverage-trend'']\n  },\n  visualization: ''grafana'',\n  alerts: {\n    critical: { bug_escape_rate: ''>20%'', mttr: ''>24h'' },\n    warning: { coverage: ''<70%'', flaky_rate: ''>5%'' }\n  }\n}, \"qe-quality-analyzer\");\n```\n\n---\n\n## Quality Gate Configuration\n\n```json\n{\n  \"qualityGates\": {\n    \"commit\": {\n      \"coverage\": { \"min\": 80, \"blocking\": true },\n      \"lint\": { \"errors\": 0, \"blocking\": true }\n    },\n    \"pr\": {\n      \"tests\": { \"pass\": \"100%\", \"blocking\": true },\n      \"security\": { \"critical\": 0, \"blocking\": true },\n      \"coverage_delta\": { \"min\": 0, \"blocking\": false }\n    },\n    \"release\": {\n      \"e2e\": { \"pass\": \"100%\", \"blocking\": true },\n      \"performance_p95\": { \"max_ms\": 200, \"blocking\": true },\n      \"bug_escape_rate\": { \"max\": \"10%\", \"blocking\": false }\n    }\n  }\n}\n```\n\n---\n\n## Agent-Assisted Metrics\n\n```typescript\n// Calculate quality trends\nawait Task(\"Quality Trend Analysis\", {\n  timeframe: ''90d'',\n  metrics: [''bug-escape-rate'', ''mttd'', ''test-effectiveness''],\n  compare: ''previous-90d'',\n  predictNext: ''30d''\n}, \"qe-quality-analyzer\");\n\n// Evaluate quality gate\nawait Task(\"Quality Gate Evaluation\", {\n  buildId: ''build-123'',\n  environment: ''staging'',\n  metrics: currentMetrics,\n  policy: qualityPolicy\n}, \"qe-quality-gate\");\n```\n\n---\n\n## Agent Coordination Hints\n\n### Memory Namespace\n```\naqe/quality-metrics/\n├── dashboards/*         - Dashboard configurations\n├── trends/*             - Historical metric data\n├── gates/*              - Gate evaluation results\n└── alerts/*             - Triggered alerts\n```\n\n### Fleet Coordination\n```typescript\nconst metricsFleet = await FleetManager.coordinate({\n  strategy: ''quality-metrics'',\n  agents: [\n    ''qe-quality-analyzer'',         // Trend analysis\n    ''qe-test-executor'',            // Test metrics\n    ''qe-coverage-analyzer'',        // Coverage data\n    ''qe-production-intelligence'',  // Production metrics\n    ''qe-quality-gate''              // Gate decisions\n  ],\n  topology: ''mesh''\n});\n```\n\n---\n\n## Common Traps\n\n| Trap | Problem | Solution |\n|------|---------|----------|\n| Coverage worship | 100% coverage, bugs still escape | Measure bug escape rate instead |\n| Test count focus | Many tests, slow feedback | Measure execution time |\n| Activity metrics | Busy work, no outcomes | Measure outcomes (MTTD, MTTR) |\n| Point-in-time | Snapshot without context | Track trends over time |\n\n---\n\n## Related Skills\n- [agentic-quality-engineering](../agentic-quality-engineering/) - Agent coordination\n- [cicd-pipeline-qe-orchestrator](../cicd-pipeline-qe-orchestrator/) - Quality gates\n- [risk-based-testing](../risk-based-testing/) - Risk-informed metrics\n- [shift-right-testing](../shift-right-testing/) - Production metrics\n\n---\n\n## Remember\n\n**Measure outcomes, not activities.** Bug escape rate > test count. MTTD/MTTR > coverage %. Trends > snapshots. Set gates that block bad code. What you measure is what you optimize.\n\n**With Agents:** Agents track metrics automatically, analyze trends, trigger alerts, and make gate decisions. Use agents to maintain continuous quality visibility.\n"},"lastSynced":"2026-03-04T13:24:39.514Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agentic API Testing Agents needing advanced quality metrics analysis and DORA metrics integration.","zh":"适用于需要高级质量指标分析和DORA指标集成的AI Agentic API测试代理。","ja":"AI Agentic APIテストエージェントが高度な品質メトリクス分析とDORAメトリクス統合を必要とする場合に最適です。","ko":"고급 품질 지표 분석 및 DORA 지표 통합이 필요한 AI Agentic API 테스트 에이전트에 적합합니다.","es":"Perfecto para Agentes de Pruebas de API de Agentic de IA que necesitan un análisis de métricas de calidad avanzado e integración de métricas DORA.","fr":"Parfait pour les Agents de Test d''API d''Agentic d''IA nécessitant une analyse de métriques de qualité avancée et une intégration de métriques DORA.","de":"Perfekt für AI Agentic API-Testagenten, die eine erweiterte Analyse von Qualitätsmetriken und eine DORA-Metrik-Integration benötigen.","pt":"Perfeito para Agentes de Teste de API de Agente de IA que necessitam de análise avançada de métricas de qualidade e integração de métricas DORA.","ru":"Идеально подходит для агентов по тестированию API искусственного интеллекта, которым требуются продвинутые метрики анализа качества и интеграция метрик DORA.","ar":"مثالي لعمليات اختبار واجهة برمجة التطبيقات للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى تحليل متقدم لقياس الجودة وتكامل مقاييس DORA."},"recommendation":{"en":"Empowers agents to measure outcomes with metrics like bug escape rate and MTTD, focus on key DORA metrics, and set quality gates to drive behavior, all while avoiding vanity metrics and trending quality over time using protocols like API testing and data formats like JSON.","zh":"赋予代理以度量结果的能力，使用诸如错误逃逸率和MTTD的指标，关注关键的DORA指标，并设置质量门控以驱动行为，同时避免虚荣指标，并使用诸如API测试和JSON等协议随时间趋势质量。","ja":"エージェントにバグエスケープレートやMTTDなどのメトリクスを使用して結果を測定し、重要なDORAメトリクスに焦点を当て、動作を駆り立てるための品質ゲートを設定し、仮のメトリクスを回避し、APIテストやJSONなどのプロトコルを使用して時間の経過とともに品質を傾向させる能力を付与します。","ko":"에이전트가 버그 탈출률 및 MTTD와 같은 지표를 사용하여 결과를 측정하고 주요 DORA 지표에 집중하고 품질 게이트를 설정하여 행동을駆使하며 가짜 지표를 피하고 API 테스트 및 JSON과 같은 프로토콜을 사용하여 시간 경과에 따라 품질을 추세하는 기능을 부여합니다.","es":"Permite a los agentes medir los resultados con métricas como la tasa de escape de errores y MTTD, centrarse en las métricas clave DORA y establecer puertas de calidad para impulsar el comportamiento, todo mientras evita las métricas vanas y las tendencias de calidad con el tiempo utilizando protocolos como las pruebas de API y formatos de datos como JSON.","fr":"Permet aux agents de mesurer les résultats avec des métriques comme le taux d''évasion de bogue et MTTD, de se concentrer sur les métriques clés DORA et de définir des portes de qualité pour stimuler le comportement, le tout en évitant les métriques vanité et les tendances de qualité dans le temps en utilisant des protocoles comme les tests d''API et des formats de données comme JSON.","de":"Ermöglicht es Agenten, Ergebnisse mit Metriken wie Fehlerentweichungsrate und MTTD zu messen, sich auf wichtige DORA-Metriken zu konzentrieren und Qualitätsziele zu setzen, um das Verhalten zu beeinflussen, alles unter Vermeidung von Vanity-Metriken und Qualitätsentwicklung im Laufe der Zeit unter Verwendung von Protokollen wie API-Tests und Datenformaten wie JSON.","pt":"Habilita os agentes a medir os resultados com métricas como taxa de escape de bugs e MTTD, focar em métricas DORA principais, e definir portas de qualidade para impulsionar o comportamento, tudo isso evitando métricas de vaidade e tendências de qualidade ao longo do tempo usando protocolos como teste de API e formatos de dados como JSON.","ru":"Наделяет агентов возможностью измерять результаты с помощью метрик, таких как скорость побега ошибок и MTTD, сосредотачиваться на ключевых метриках DORA, и устанавливать ворота качества для стимулирования поведения, все это избегая метрик тщеславия и тенденций качества во времени с использованием протоколов, таких как тестирование API, и форматов данных, таких как JSON.","ar":"يتمكّن الوكلاء من قياس النتائج باستخدام مقاييس مثل معدل هروب العيوب و MTTR، والتركيز على مقاييس DORA الرئيسية، وتحديد بوابات الجودة لدفع السلوك، كل ذلك مع تجنب مقاييس التخيل والاتجاهات الجودة مع مرور الوقت باستخدام بروتوكولات مثل اختبار واجهة برمجة التطبيقات وصيغ البيانات مثل JSON."},"useCases":{"en":["Measuring deployment frequency and lead time","Tracking mean time to detect and recover from failures","Setting thresholds for quality gates to block bad code"],"zh":["测量部署频率和引导时间","跟踪检测和恢复故障的平均时间","为质量门控设置阈值以阻止糟糕的代码"],"ja":["デプロイ頻度とリードタイムを測定する","障害の検出と回復の平均時間を追跡する","悪いコードをブロックするために品質ゲートのしきい値を設定する"],"ko":["배포 빈도 및 리드 타임 측정","故障 Detection 및 복구 평균 시간 추적","나쁨 코드 차단을위한 품질 게이트 임계값 설정"],"es":["Medir la frecuencia de implementación y el tiempo de ejecución","Seguir el tiempo medio de detección y recuperación de fallos","Establecer umbrales para las puertas de calidad para bloquear el código malo"],"fr":["Mesurer la fréquence de déploiement et le temps de latence","Suivre le temps moyen de détection et de récupération des défaillances","Définir des seuils pour les portes de qualité pour bloquer le code défectueux"],"de":["Messung der Bereitstellungs- und Leadzeit","Nachverfolgung der mittleren Zeit zur Erkennung und Wiederherstellung nach Fehlern","Festlegung von Schwellenwerten für Qualitätsziele, um schlechten Code zu blockieren"],"pt":["Medir a frequência de implantação e o tempo de lead","Rastrear o tempo médio para detectar e se recuperar de falhas","Definir limites para portas de qualidade para bloquear código ruim"],"ru":["Измерять частоту развертывания и время лидерства","Отслеживать среднее время для обнаружения и восстановления после сбоев","Устанавливать пороги для ворот качества для блокировки плохого кода"],"ar":["قياس وتيرة النشر ووقت قائد","تتبع متوسط الوقت للكشف عن الاستعادة من الفشل","تعيين حدود لبوابات الجودة لمنع رمز سيئ"]},"limitations":{"en":["Requires understanding of DORA metrics and API testing protocols","Limited to measuring outcomes and trends, not activities or absolute numbers"],"zh":["需要了解DORA指标和API测试协议","仅限于测量结果和趋势，而不是活动或绝对数字"],"ja":["DORAメトリクスとAPIテストプロトコルの理解が必要","結果と傾向のみを測定し、活動や絶対数は測定しない"],"ko":["DORA 지표 및 API 테스트 프로토콜에 대한 이해가 필요","결과 및 추세만 측정하고 활동 또는 절대 수는 측정하지 않음"],"es":["Requiere comprensión de las métricas DORA y los protocolos de pruebas de API","Limitado a la medición de resultados y tendencias, no actividades o números absolutos"],"fr":["Nécessite une compréhension des métriques DORA et des protocoles de test d''API","Limité à la mesure des résultats et des tendances, et non des activités ou des nombres absolus"],"de":["Erfordert das Verständnis von DORA-Metriken und API-Testprotokollen","Begrenzt auf die Messung von Ergebnissen und Trends, nicht Aktivitäten oder absolute Zahlen"],"pt":["Requer entendimento de métricas DORA e protocolos de teste de API","Limitado a medir resultados e tendências, não atividades ou números absolutos"],"ru":["Требует понимания метрик DORA и протоколов тестирования API","Ограничен измерением результатов и тенденций, а не деятельности или абсолютных чисел"],"ar":["يتطلب فهم مقاييس DORA وبروتوكولات اختبار واجهة برمجة التطبيقات","محدود بقياس النتائج والاتجاهات، وليس الأنشطة أو الأرقام المطلقة"]},"version":3},"contentHash":"6368fc153b1626be1079ca4c5694b9276dfa9315cf481fe722e6f9fb31504671","qualityScore":56}');
