INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('attasec/tmdd/tmdd-threat-modeling', 'tmdd-threat-modeling', 'attasec', 'tmdd', 'community', 'tmdd-threat-modeling attasec tmdd community tmdd威胁建模CLI工具是一种用于持续威胁建模的命令行工具，帮助开发者增强安全性。 tmdd脅威モデルCLIツールは、継続的な脅威モデルを作成するためのコマンドラインツールです。 tmdd 위협 모델링 CLI 도구는 지속적인 위협 모델링을 위한 명령줄 도구로서 개발자가 보안을 강화하는 데 도움을 줍니다. tmdd-threat-modeling es una herramienta de línea de comandos para el modelado de amenazas continuo tmdd-threat-modeling est un outil de ligne de commande pour la modélisation de menaces continue tmdd-threat-modeling ist ein Kommandozeilen-Tool für die kontinuierliche Bedrohungsmodellierung O tmdd-threat-modeling é uma ferramenta CLI para modelagem de ameaças contínua, ajudando a melhorar a segurança dos projetos tmdd-threat-modeling - это инструмент ИИ Агенты для непрерывного моделирования угроз, помогающий улучшить безопасность проектов tmdd-threat-modeling هو أداة نمذجة التهديدات المستمرة، تساعد على تحسين أمان المشاريع CLI tool for Continuous Threat Modeling tmdd威胁建模 CLI工具 持续威胁建模 安全性增强 AIエージェント 如何使用tmdd tmdd安装 tmdd设置指南 CLI tool for Continuous Threat Modeling');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AgentWorkforce/trajectories/creating-skills', 'community', 'AgentWorkforce', 'trajectories', 'AgentWorkforce/trajectories', 'creating-skills', 13, 0, 55, '2026-02-24T19:54:10Z', '2026-02-26T08:33:52.602Z', '2d5916eb2f7648cdb34fd17df7a5975a69eafd4f3265e96bc0f52b3b2d10df7a', '{"id":"AgentWorkforce/trajectories/creating-skills","name":"creating-skills","description":{"zh":"创建技能是AI智能代理的文档层，用于实现高效的Agent工作","ja":"スキル作成はAIエージェントのドキュメントレイヤーであり、エージェントの仕事を効率化するためのもの","ko":"스킬 생성은 AI 에이전트의 문서 레이어로서 에이전트 작업을 효율화하는 데 사용","es":"Nuestra documentación de capa de trabajo permite a los desarrolladores crear habilidades para Agentes de IA de manera eficiente","fr":"Notre documentation de couche de travail permet aux développeurs de créer des compétences pour les Agents IA de manière efficace","de":"Unsere Arbeitsdokumentation ermöglicht es Entwicklern, Fähigkeiten für KI-Agenten effizient zu erstellen","pt":"A documentação de camada de trabalho para agentes de IA permite a criação de habilidades personalizadas","ru":"Документация слоя работы для ИИ Агентов позволяет создавать индивидуальные навыки","ar":"وثائق طبقة العمل لوكلاء الذكاء الاصطناعي تسمح بإنشاء مهارات مخصصة","en":"Document layer for agent work"},"seo":{"title":{"zh":"AI智能代理创建技能","ja":"AIエージェントのスキル作成","ko":"AI 에이전트 스킬 생성","es":"Herramientas de creación de habilidades para Agentes de IA","fr":"Outils de création de compétences pour les Agents IA","de":"Erstellungstools für KI-Agenten-Fähigkeiten","pt":"Criar Habilidades de Agente de IA","ru":"ИИ Агенты: Создание Навыков","ar":"وكلاء الذكاء الاصطناعي: إنشاء المهارات","en":"creating-skills"},"description":{"zh":"创建技能是AI智能代理的文档层，用于实现高效的Agent工作","ja":"スキル作成はAIエージェントのドキュメントレイヤーであり、エージェントの仕事を効率化するためのもの","ko":"스킬 생성은 AI 에이전트의 문서 레이어로서 에이전트 작업을 효율화하는 데 사용","es":"Nuestra documentación de capa de trabajo permite a los desarrolladores crear habilidades para Agentes de IA de manera eficiente","fr":"Notre documentation de couche de travail permet aux développeurs de créer des compétences pour les Agents IA de manière efficace","de":"Unsere Arbeitsdokumentation ermöglicht es Entwicklern, Fähigkeiten für KI-Agenten effizient zu erstellen","pt":"A documentação de camada de trabalho para agentes de IA permite a criação de habilidades personalizadas","ru":"Документация слоя работы для ИИ Агентов позволяет создавать индивидуальные навыки","ar":"وثائق طبقة العمل لوكلاء الذكاء الاصطناعي تسمح بإنشاء مهارات مخصصة","en":"Document layer for agent work"},"definition":{"en":"Document layer for agent work"},"features":{"zh":["支持多种文档格式","高效的文档管理","实现Agent工作自动化","支持React、Python、Node.js等开发框架","提供CLI工具用于快速开发","支持Agent工作流程自定义"],"ja":["複数のドキュメント形式をサポート","効率的なドキュメント管理","エージェントの仕事を自動化","React、Python、Node.jsなどの開発フレームワークをサポート","CLIツールを使用した迅速な開発","エージェントの仕事の流れをカスタマイズ"],"ko":["다중 문서 형식을 지원","효율적인 문서 관리","에이전트 작업 자동화","React, Python, Node.js 등의 개발 프레임워크 지원","CLI 도구를 사용한 빠른 개발","에이전트 작업 흐름을 사용자 정의"],"es":["Documentación de capa de trabajo para Agentes de IA","Creación de habilidades personalizadas","Integración con tecnologías como React y Node.js","Compatibilidad con CLI para una implementación sencilla","Soporte para el desarrollo de habilidades avanzadas"],"fr":["Documentation de couche de travail pour les Agents IA","Création de compétences personnalisées","Intégration avec des technologies comme React et Node.js","Compatibilité avec CLI pour une mise en œuvre simple","Prise en charge du développement de compétences avancées"],"de":["Arbeitsdokumentation für KI-Agenten","Erstellung von benutzerdefinierten Fähigkeiten","Integration mit Technologien wie React und Node.js","Kompatibilität mit CLI für eine einfache Implementierung","Unterstützung für die Entwicklung von erweiterten Fähigkeiten"],"pt":["Criação de habilidades personalizadas","Integração com React e Node.js","Suporte a CLI para agentes de IA","Documentação de camada de trabalho","Suporte a Python para desenvolvimento de agentes"],"ru":["Создание индивидуальных навыков","Интеграция с React и Node.js","Поддержка CLI для ИИ Агентов","Документация слоя работы","Поддержка Python для разработки агентов"],"ar":["إنشاء مهارات مخصصة","التكامل مع React و Node.js","دعم CLI لوكلاء الذكاء الاصطناعي","وثائق طبقة العمل","دعم Python لتطوير الوكلاء"]},"keywords":{"zh":["AI智能代理创建技能","如何使用AI智能代理","什么是AI智能代理","AI智能代理替代品","AI智能代理与其他工具的比较","AI智能代理安装指南","AI智能代理设置教程","使用React开发AI智能代理","使用Python开发AI智能代理"],"ja":["AIエージェントのスキル作成","AIエージェントの使用方法","AIエージェントとは","AIエージェントの代替品","AIエージェントと他のツールの比較","AIエージェントのインストールガイド","AIエージェントの設定手順","Reactを使用したAIエージェントの開発","Pythonを使用したAIエージェントの開発"],"ko":["AI 에이전트 스킬 생성","AI 에이전트 사용 방법","AI 에이전트란","AI 에이전트 대안","AI 에이전트와 다른 도구의 비교","AI 에이전트 설치 가이드","AI 에이전트 설정 튜토리얼","React를 사용한 AI 에이전트 개발","Python을 사용한 AI 에이전트 개발"],"es":["cómo crear habilidades para Agentes de IA","herramientas de creación de habilidades para Agentes de IA","Agentes de IA alternativos","Agentes de IA vs herramientas de automatización","instalación de Agentes de IA","guía de configuración de Agentes de IA","desarrollo de habilidades para Agentes de IA","integración de Agentes de IA con React","uso de Node.js con Agentes de IA"],"fr":["comment créer des compétences pour les Agents IA","outils de création de compétences pour les Agents IA","Agents IA alternatifs","Agents IA vs outils d''automatisation","installation des Agents IA","guide de configuration des Agents IA","développement de compétences pour les Agents IA","intégration des Agents IA avec React","utilisation de Node.js avec les Agents IA"],"de":["wie man Fähigkeiten für KI-Agenten erstellt","Erstellungstools für KI-Agenten-Fähigkeiten","KI-Agenten-Alternativen","KI-Agenten vs Automatisierungstools","Installation von KI-Agenten","Konfigurationsanleitung für KI-Agenten","Entwicklung von Fähigkeiten für KI-Agenten","Integration von KI-Agenten mit React","Verwendung von Node.js mit KI-Agenten"],"pt":["como usar agentes de IA","o que é agente de IA","alternativa ao Dialogflow","instalação de agentes de IA","guia de configuração de agentes de IA","desenvolvimento de habilidades de agente de IA"],"ru":["как использовать ИИ Агентов","что такое ИИ Агент","альтернатива Dialogflow","установка ИИ Агентов","руководство по настройке ИИ Агентов","разработка навыков ИИ Агентов"],"ar":["كيفية استخدام وكلاء الذكاء الاصطناعي","ما هو وكيل الذكاء الاصطناعي","بديل ل Dialogflow","تثبيت وكلاء الذكاء الاصطناعي","دليل إعداد وكلاء الذكاء الاصطناعي","تطوير مهارات وكلاء الذكاء الاصطناعي"]}},"owner":"AgentWorkforce","repo":"trajectories","repoPath":"AgentWorkforce/trajectories","stars":13,"forks":0,"updatedAt":"2026-02-24T19:54:10Z","topics":[],"category":"community","skillMd":{"name":"creating-skills","description":"Use when creating new Claude Code skills or improving existing ones - ensures skills are discoverable, scannable, and effective through proper structure, CSO optimization, and real examples","bodyPreview":"# Creating Skills\n\n## Overview\n\n**Skills are reference guides for proven techniques, patterns, or tools.** Write them to help future Claude instances quickly find and apply effective approaches.\n\nSkills must be **discoverable** (Claude can find them), **scannable** (quick to evaluate), and **actionable** (clear examples).\n\n**Core principle**: Default assumption is Claude is already very smart. Only add context Claude doesn''t already have.\n\n## When to Use\n\n**Create a skill when:**\n- Technique was","body":"# Creating Skills\n\n## Overview\n\n**Skills are reference guides for proven techniques, patterns, or tools.** Write them to help future Claude instances quickly find and apply effective approaches.\n\nSkills must be **discoverable** (Claude can find them), **scannable** (quick to evaluate), and **actionable** (clear examples).\n\n**Core principle**: Default assumption is Claude is already very smart. Only add context Claude doesn''t already have.\n\n## When to Use\n\n**Create a skill when:**\n- Technique wasn''t intuitively obvious\n- Pattern applies broadly across projects\n- You''d reference this again\n- Others would benefit\n\n**Don''t create for:**\n- One-off solutions specific to single project\n- Standard practices well-documented elsewhere\n- Project conventions (put those in `.claude/CLAUDE.md`)\n\n## Required Structure\n\n### Frontmatter (YAML)\n\n```yaml\n---\nname: skill-name-with-hyphens\ndescription: Use when [triggers/symptoms] - [what it does and how it helps]\ntags: relevant-tags\n---\n```\n\n**Rules:**\n- Only `name` and `description` fields supported (max 1024 chars total)\n- Name: letters, numbers, hyphens only (max 64 chars). Use gerund form (verb + -ing)\n- Avoid reserved words: \"anthropic\", \"claude\" in names\n- Description: Third person, starts with \"Use when...\" (max 1024 chars)\n- Include BOTH triggering conditions AND what skill does\n- Match specificity to task complexity (degrees of freedom)\n\n### Document Structure\n\n```markdown\n# Skill Name\n\n## Overview\nCore principle in 1-2 sentences. What is this?\n\n## When to Use\n- Bullet list with symptoms and use cases\n- When NOT to use\n\n## Quick Reference\nTable or bullets for common operations\n\n## Implementation\nInline code for simple patterns\nLink to separate file for heavy reference (100+ lines)\n\n## Common Mistakes\nWhat goes wrong + how to fix\n\n## Real-World Impact (optional)\nConcrete results from using this technique\n```\n\n## Degrees of Freedom\n\n**Match specificity to task complexity:**\n\n- **High freedom**: Flexible tasks requiring judgment\n  - Use broad guidance, principles, examples\n  - Let Claude adapt approach to context\n  - Example: \"Use when designing APIs - provides REST principles and patterns\"\n\n- **Low freedom**: Fragile or critical operations\n  - Be explicit about exact steps\n  - Include validation checks\n  - Example: \"Use when deploying to production - follow exact deployment checklist with rollback procedures\"\n\n**Red flag**: If skill tries to constrain Claude too much on creative tasks, reduce specificity. If skill is too vague on critical operations, add explicit steps.\n\n## Claude Search Optimization (CSO)\n\n**Critical:** Future Claude reads the description to decide if skill is relevant. Optimize for discovery.\n\n### Description Best Practices\n\n```yaml\n# ❌ BAD - Too vague, doesn''t mention when to use\ndescription: For async testing\n\n# ❌ BAD - First person (injected into system prompt)\ndescription: I help you with flaky tests\n\n# ✅ GOOD - Triggers + what it does\ndescription: Use when tests have race conditions or pass/fail inconsistently - replaces arbitrary timeouts with condition polling for reliable async tests\n\n# ✅ GOOD - Technology-specific with explicit trigger\ndescription: Use when using React Router and handling auth redirects - provides patterns for protected routes and auth state management\n```\n\n### Keyword Coverage\n\nUse words Claude would search for:\n- **Error messages**: \"ENOENT\", \"Cannot read property\", \"Timeout\"\n- **Symptoms**: \"flaky\", \"hanging\", \"race condition\", \"memory leak\"\n- **Synonyms**: \"cleanup/teardown/afterEach\", \"timeout/hang/freeze\"\n- **Tools**: Actual command names, library names, file types\n\n### Naming Conventions\n\n**Use gerund form (verb + -ing):**\n- ✅ `creating-skills` not `skill-creation`\n- ✅ `testing-with-subagents` not `subagent-testing`\n- ✅ `debugging-memory-leaks` not `memory-leak-debugging`\n- ✅ `processing-pdfs` not `pdf-processor`\n- ✅ `analyzing-spreadsheets` not `spreadsheet-analysis`\n\n**Why gerunds work:**\n- Describes the action you''re taking\n- Active and clear\n- Consistent with Anthropic conventions\n\n**Avoid:**\n- ❌ Vague names like \"Helper\" or \"Utils\"\n- ❌ Passive voice constructions\n\n## Code Examples\n\n**One excellent example beats many mediocre ones.**\n\n### Choose Language by Use Case\n\n- Testing techniques → TypeScript/JavaScript\n- System debugging → Shell/Python\n- Data processing → Python\n- API calls → TypeScript/JavaScript\n\n### Good Example Checklist\n\n- [ ] Complete and runnable\n- [ ] Well-commented explaining **WHY** not just what\n- [ ] From real scenario (not contrived)\n- [ ] Shows pattern clearly\n- [ ] Ready to adapt (not generic template)\n- [ ] Shows both BAD (❌) and GOOD (✅) approaches\n- [ ] Includes realistic context/setup code\n\n### Example Template\n\n```typescript\n// ✅ GOOD - Clear, complete, ready to adapt\ninterface RetryOptions {\n  maxAttempts: number;\n  delayMs: number;\n  backoff?: ''linear'' | ''exponential'';\n}\n\nasync function retryOperation<T>(\n  operation: () => Promise<T>,\n  options: RetryOptions\n): Promise<T> {\n  const { maxAttempts, delayMs, backoff = ''linear'' } = options;\n\n  for (let attempt = 1; attempt <= maxAttempts; attempt++) {\n    try {\n      return await operation();\n    } catch (error) {\n      if (attempt === maxAttempts) throw error;\n\n      const delay = backoff === ''exponential''\n        ? delayMs * Math.pow(2, attempt - 1)\n        : delayMs * attempt;\n\n      await new Promise(resolve => setTimeout(resolve, delay));\n    }\n  }\n\n  throw new Error(''Unreachable'');\n}\n\n// Usage\nconst data = await retryOperation(\n  () => fetchUserData(userId),\n  { maxAttempts: 3, delayMs: 1000, backoff: ''exponential'' }\n);\n```\n\n### Don''t\n\n- ❌ Implement in 5+ languages (you''re good at porting)\n- ❌ Create fill-in-the-blank templates\n- ❌ Write contrived examples\n- ❌ Show only code without comments\n\n## File Organization\n\n### Self-Contained (Preferred)\n\n```\ntypescript-type-safety/\n  SKILL.md    # Everything inline\n```\n\n**When:** All content fits in ~500 words, no heavy reference needed\n\n### With Supporting Files\n\n```\napi-integration/\n  SKILL.md           # Overview + patterns\n  retry-helpers.ts   # Reusable code\n  examples/\n    auth-example.ts\n    pagination-example.ts\n```\n\n**When:** Reusable tools or multiple complete examples needed\n\n### With Heavy Reference\n\n```\naws-sdk/\n  SKILL.md       # Overview + workflows\n  s3-api.md      # 600 lines API reference\n  lambda-api.md  # 500 lines API reference\n```\n\n**When:** Reference material > 100 lines\n\n## Token Efficiency\n\nSkills load into every conversation. Keep them concise.\n\n### Target Limits\n\n- **SKILL.md**: Keep under 500 lines\n- Getting-started workflows: <150 words\n- Frequently-loaded skills: <200 words total\n- Other skills: <500 words\n- Files > 100 lines: Include table of contents\n\n**Challenge each piece of information**: \"Does Claude really need this explanation?\"\n\n### Compression Techniques\n\n```markdown\n# ❌ BAD - Verbose (42 words)\nYour human partner asks: \"How did we handle authentication errors in React Router before?\"\nYou should respond: \"I''ll search past conversations for React Router authentication patterns.\"\nThen dispatch a subagent with the search query: \"React Router authentication error handling 401\"\n\n# ✅ GOOD - Concise (20 words)\nPartner: \"How did we handle auth errors in React Router?\"\nYou: Searching...\n[Dispatch subagent → synthesis]\n```\n\n**Techniques:**\n- Reference tool `--help` instead of documenting all flags\n- Cross-reference other skills instead of repeating content\n- Show minimal example of pattern\n- Eliminate redundancy\n- Use progressive disclosure (reference additional files as needed)\n- Organize content by domain for focused context\n\n## Workflow Recommendations\n\nFor multi-step processes, include:\n\n1. **Clear sequential steps**: Break complex tasks into numbered operations\n2. **Feedback loops**: Build in verification/validation steps\n3. **Error handling**: What to check when things go wrong\n4. **Checklists**: For processes with many steps or easy-to-miss details\n\n**Example structure:**\n```markdown\n## Workflow\n\n1. **Preparation**\n   - Check prerequisites\n   - Validate environment\n\n2. **Execution**\n   - Step 1: [action + expected result]\n   - Step 2: [action + expected result]\n\n3. **Verification**\n   - [ ] Check 1 passes\n   - [ ] Check 2 passes\n\n4. **Rollback** (if needed)\n   - Steps to undo changes\n```\n\n## Common Mistakes\n\n| Mistake | Why It Fails | Fix |\n|---------|--------------|-----|\n| Narrative example | \"In session 2025-10-03...\" | Focus on reusable pattern |\n| Multi-language dilution | Same example in 5 languages | One excellent example |\n| Code in flowcharts | `step1 [label=\"import fs\"]` | Use markdown code blocks |\n| Generic labels | helper1, helper2, step3 | Use semantic names |\n| Missing description triggers | \"For testing\" | \"Use when tests are flaky...\" |\n| First-person description | \"I help you...\" | \"Use when... - provides...\" |\n| Deeply nested file references | Multiple @ symbols, complex paths | Keep references simple and direct |\n| Windows-style file paths | `C:\\path\\to\\file` | Use forward slashes |\n| Offering too many options | 10 different approaches | Focus on one proven approach |\n| Punting error handling | \"Claude figures it out\" | Include explicit error handling in scripts |\n| Time-sensitive information | \"As of 2025...\" | Keep content evergreen |\n| Inconsistent terminology | Mixing synonyms randomly | Use consistent terms throughout |\n\n## Flowchart Usage\n\n**Only use flowcharts for:**\n- Non-obvious decision points\n- Process loops where you might stop too early\n- \"When to use A vs B\" decisions\n\n**Never use for:**\n- Reference material → Use tables/lists\n- Code examples → Use markdown blocks\n- Linear instructions → Use numbered lists\n\n## Cross-Referencing Skills\n\n```markdown\n# ✅ GOOD - Name only with clear requirement\n**REQUIRED:** Use superpowers:test-driven-development before proceeding\n\n**RECOMMENDED:** See typescript-type-safety for proper type guards\n\n# ❌ BAD - Unclear if required\nSee skills/testing/test-driven-development\n\n# ❌ BAD - Force-loads file, wastes context\n@skills/testing/test-driven-development/SKILL.md\n```\n\n## Advanced Practices\n\n### Iterative Development\n\n**Best approach**: Develop skills iteratively with Claude\n1. Start with minimal viable skill\n2. Test with real use cases\n3. Refine based on what works\n4. Remove what doesn''t add value\n\n### Build Evaluations First\n\nBefore extensive documentation:\n1. Create test scenarios\n2. Identify what good looks like\n3. Document proven patterns\n4. Skip theoretical improvements\n\n### Utility Scripts\n\nFor reliability, provide:\n- Scripts with explicit error handling (don''t defer errors to Claude)\n- Exit codes for success/failure\n- Clear error messages\n- Examples of usage\n- List required dependencies explicitly\n\n**Example:**\n```bash\n#!/bin/bash\nset -e  # Exit on error\n\nif [ ! -f \"config.json\" ]; then\n  echo \"Error: config.json not found\" >&2\n  exit 1\nfi\n\n# Script logic here\necho \"Success\"\nexit 0\n```\n\n### Verifiable Intermediate Outputs\n\nFor complex operations, create validation checkpoints:\n1. Have Claude produce a structured plan file\n2. Validate the plan with a script\n3. Execute only after validation passes\n\nThis catches errors before they compound.\n\n### Templates for Structured Output\n\nWhen skills produce consistent formats:\n```markdown\n## Output Template\n\n\\`\\`\\`typescript\ninterface ExpectedOutput {\n  status: ''success'' | ''error'';\n  data: YourDataType;\n  errors?: string[];\n}\n\\`\\`\\`\n\n**Usage**: Copy and adapt for your context\n```\n\n## Skill Creation Checklist\n\n**Before writing:**\n- [ ] Technique isn''t obvious or well-documented elsewhere\n- [ ] Pattern applies broadly (not project-specific)\n- [ ] I would reference this across multiple projects\n\n**Frontmatter:**\n- [ ] Name uses only letters, numbers, hyphens\n- [ ] Description starts with \"Use when...\"\n- [ ] Description includes triggers AND what skill does\n- [ ] Description is third person\n- [ ] Total frontmatter < 1024 characters\n\n**Content:**\n- [ ] Overview states core principle (1-2 sentences)\n- [ ] \"When to Use\" section with symptoms\n- [ ] Quick reference table for common operations\n- [ ] One excellent code example (if technique skill)\n- [ ] Common mistakes section\n- [ ] Keywords throughout for searchability\n\n**Quality:**\n- [ ] Word count appropriate for frequency (see targets above)\n- [ ] SKILL.md under 500 lines\n- [ ] No narrative storytelling\n- [ ] Flowcharts only for non-obvious decisions\n- [ ] Supporting files only if needed (100+ lines reference)\n- [ ] Cross-references use skill name, not file paths\n- [ ] No time-sensitive information\n- [ ] Consistent terminology throughout\n- [ ] Concrete examples (not templates)\n- [ ] Degrees of freedom match task complexity\n\n**Testing:**\n- [ ] Tested with Claude Haiku, Sonnet, and Opus (instructions effective for Opus may need more detail for Haiku)\n- [ ] Tested with subagent scenarios (if discipline-enforcing skill)\n- [ ] Addresses common rationalizations\n- [ ] Includes red flags list\n\n## Directory Structure\n\n```\nskills/\n  skill-name/\n    SKILL.md              # Required\n    supporting-file.*     # Optional\n    examples/             # Optional\n      example1.ts\n    scripts/              # Optional\n      helper.py\n```\n\n**Flat namespace** - all skills in one searchable directory\n\n## Real-World Impact\n\n**Good skills:**\n- Future Claude finds them quickly (CSO optimization)\n- Can be scanned in seconds (quick reference)\n- Provide clear actionable examples\n- Prevent repeating same research\n- Stay under 500 lines (token efficient)\n- Match specificity to task needs (right degrees of freedom)\n\n**Bad skills:**\n- Get ignored (vague description)\n- Take too long to evaluate (no quick reference)\n- Leave gaps in understanding (no examples)\n- Waste token budget (verbose explanations of obvious things)\n- Over-constrain creative tasks or under-specify critical operations\n- Include time-sensitive or obsolete information\n\n---\n\n**Remember:** Skills are for future Claude, not current you. Optimize for discovery, scanning, and action.\n\n**Golden rule:** Default assumption is Claude is already very smart. Only add context Claude doesn''t already have."},"lastSynced":"2026-02-26T08:33:52.602Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Claude, Cursor, and AutoGPT needing to develop and share proven techniques and patterns.","zh":"适合于需要开发和分享成熟技术和模式的AI代理，如Claude、Cursor和AutoGPT。","ja":"Claude、Cursor、AutoGPTなどのAIエージェントが成熟したテクニックとパターンを開発して共有する必要がある場合に最適です。","ko":"클라우드, 커서, 오utoGPT와 같은 AI 에이전트가 성숙한 기술과 패턴을 개발하고 공유해야 하는 경우에 적합합니다.","es":"Perfecto para agentes de IA como Claude, Cursor y AutoGPT que necesitan desarrollar y compartir técnicas y patrones probados.","fr":"Parfait pour les agents IA comme Claude, Cursor et AutoGPT ayant besoin de développer et de partager des techniques et des modèles éprouvés.","de":"Perfekt für KI-Agents wie Claude, Cursor und AutoGPT, die bewährte Techniken und Muster entwickeln und teilen müssen.","pt":"Perfeito para agentes de IA como Claude, Cursor e AutoGPT que precisam desenvolver e compartilhar técnicas e padrões comprovados.","ru":"Идеально подходит для агентов ИИ, таких как Claude, Cursor и AutoGPT, которым необходимо разработать и поделиться проверенными методами и шаблонами.","ar":"مثالي لوكلاء الذكاء الاصطناعي مثل Claude و Cursor و AutoGPT الذين يحتاجون إلى تطوير وتبادل تقنيات وأنماط محكمة"},"recommendation":{"en":"Empowers agents to create discoverable, scannable, and actionable skills using reference guides, enabling them to quickly find and apply effective approaches with techniques and tools, defaulting to the assumption that the agent is already very smart and only adding necessary context.","zh":"赋予代理创建可发现、可扫描和可执行的技能的能力，使用参考指南，使他们能够快速找到并应用有效的方法和技术，假设代理已经非常智能，只添加必要的上下文。","ja":"エージェントが参考ガイドを使用して、発見可能、スキャナブル、実行可能なスキルを作成できるようにし、エージェントがすでに非常に賢いという前提で、すぐに効果的なアプローチを見つけて適用できるようにします。","ko":"에이전트가 참조 가이드를 사용하여 발견 가능한, 스캔 가능한, 실행 가능한 스킬을 만들 수 있는 능력을 부여하여 에이전트가すぐ에 효과적인 접근 방식을 찾고 적용할 수 있도록 하며, 에이전트가 이미 매우 지능적이라는 가정하에 필요한 컨텍스트만 추가합니다.","es":"Habilita a los agentes a crear habilidades descubribles, escaneables y accionables utilizando guías de referencia, lo que les permite encontrar y aplicar rápidamente enfoques efectivos con técnicas y herramientas, asumiendo que el agente ya es muy inteligente y solo agregando el contexto necesario.","fr":"Permet aux agents de créer des compétences découvrables, scannables et actionnables en utilisant des guides de référence, leur permettant de trouver et d''appliquer rapidement des approches efficaces avec des techniques et des outils, en supposant que l''agent est déjà très intelligent et en n''ajoutant que le contexte nécessaire.","de":"Ermöglicht es Agenten, entdeckbare, scannbare und ausführbare Fähigkeiten mithilfe von Referenzhandbüchern zu erstellen, sodass sie schnell effektive Ansätze mit Techniken und Werkzeugen finden und anwenden können, unter der Annahme, dass der Agent bereits sehr intelligent ist und nur notwendigen Kontext hinzufügt.","pt":"Habilita os agentes a criar habilidades descobríveis, scaneáveis e ações usando guias de referência, permitindo que eles encontrem e apliquem abordagens eficazes com técnicas e ferramentas, partindo do pressuposto de que o agente já é muito inteligente e adicionando apenas o contexto necessário.","ru":"Наделяет агентов возможностью создавать обнаруживаемые, сканируемые и действенные навыки с помощью справочных руководств, что позволяет им быстро находить и применять эффективные подходы с помощью техник и инструментов, исходя из предположения, что агент уже очень умён и добавляя только необходимый контекст.","ar":"تمكّن الوكلاء من إنشاء مهارات يمكن اكتشافها وفحصها وتطبيقها باستخدام أدلة مرجعية، مما يسمح لهم بالعثور على وتطبيق نهج فعال باستخدام تقنيات وأدوات، افتراضًا أن الوكيل بالفعل ذكي للغاية وإضافة السياق اللازم فقط"},"useCases":{"en":["Documenting proven techniques for future agent instances","Creating scannable guides for quick evaluation and application","Developing actionable examples for effective approach execution"],"zh":["为未来的代理实例记录成熟的技术","创建可扫描的指南以便于快速评估和应用","开发可执行的示例以有效地执行方法"],"ja":["将来のエージェントインスタンスのために確立されたテクニックを文書化する","迅速な評価と適用のためにスキャナブルなガイドを作成する","有効なアプローチの実行のためのアクション可能な例を開発する"],"ko":["미래의 에이전트 인스턴스에 대한 성숙한 기술을 문서화하는 것","迅速한 평가 및 적용을 위한 스캔 가능한 가이드 생성","유효한 접근 방식의 실행을 위한 실행 가능한 예제 개발"],"es":["Documentar técnicas probadas para futuras instancias de agentes","Crear guías escaneables para una evaluación y aplicación rápidas","Desarrollar ejemplos accionables para la ejecución efectiva de enfoques"],"fr":["Documenter des techniques éprouvées pour les instances d''agents futures","Créer des guides scannables pour une évaluation et une application rapides","Développer des exemples actionnables pour l''exécution efficace des approches"],"de":["Bewährte Techniken für zukünftige Agenten-Instanzen zu dokumentieren","Scannbare Handbücher für eine schnelle Bewertung und Anwendung erstellen","Auszuführende Beispiele für die effektive Ausführung von Ansätzen entwickeln"],"pt":["Documentar técnicas comprovadas para instâncias futuras de agentes","Criar guias scaneáveis para avaliação e aplicação rápidas","Desenvolver exemplos ações para execução de abordagens eficazes"],"ru":["Документирование проверенных методов для будущих экземпляров агентов","Создание сканируемых руководств для быстрой оценки и применения","Разработка действенных примеров для эффективной реализации подходов"],"ar":["توثيق تقنيات محكمة للوكلاء في المستقبل","إنشاء أدلة يمكن فحصها لالتقاط سريع وتطبيق","تطوير أمثلة يمكن تطبيقها لتنفيذ نهج فعال"]},"limitations":{"en":["Requires understanding of core principle that agents are already very smart","Needs adherence to discoverable, scannable, and actionable skill structure"],"zh":["需要理解核心原则，即代理已经非常智能","需要遵循可发现、可扫描和可执行的技能结构"],"ja":["エージェントはすでに非常に賢いという核心原則を理解する必要がある","発見可能、スキャナブル、実行可能なスキル構造に従う必要がある"],"ko":["에이전트가 이미 매우 지능적이라는 핵심 원리를 이해해야 함","발견 가능한, 스캔 가능한, 실행 가능한 스킬 구조를 따라야 함"],"es":["Requiere comprensión del principio básico de que los agentes ya son muy inteligentes","Necesita adherirse a la estructura de habilidades descubribles, escaneables y accionables"],"fr":["Nécessite une compréhension du principe de base que les agents sont déjà très intelligents","Nécessite l''adhésion à la structure de compétences découvrables, scannables et actionnables"],"de":["Benötigt das Verständnis der Grundprämisse, dass Agents bereits sehr intelligent sind","Benötigt die Einhaltung der Struktur von entdeckbaren, scannbaren und ausführbaren Fähigkeiten"],"pt":["Exige compreensão do princípio básico de que os agentes já são muito inteligentes","Necessita de aderência à estrutura de habilidades descobríveis, scaneáveis e ações"],"ru":["Требует понимания базового принципа, что агенты уже очень умны","Требует соблюдения структуры навыков, обнаруживаемых, сканируемых и действенных"],"ar":["يتطلب فهم المبدأ الأساسي أن الوكلاء بالفعل ذكي للغاية","يتطلب الالتزام بهيكل مهارات يمكن اكتشافها وفحصها وتطبيقها"]},"version":3},"contentHash":"2d5916eb2f7648cdb34fd17df7a5975a69eafd4f3265e96bc0f52b3b2d10df7a","qualityScore":55}');
