INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nxy7/streampai-elixir/document', 'document', 'nxy7', 'streampai-elixir', 'community', 'document nxy7 streampai-elixir community Streampai是实时应用AI工具，帮助管理LiveStreams。它提供实时应用管理功能，帮助开发者高效管理LiveStreams StreampaiはリアルタイムアプリケーションAIエージェントであり、LiveStreamsを管理するために役立ちます。開発者はこのツールを使用して、高効率でLiveStreamsを管理できます Streampai는 실시간 애플리케이션 AI 에이전트로 LiveStreams를 관리하는 데 도움이 됩니다. 개발자는 이 도구를 사용하여 효율적으로 LiveStreams를 관리할 수 있습니다 Streampai es una aplicación en tiempo real que ayuda a gestionar LiveStreams con herramientas de AI. Mejora tu desarrollo con nuestra documentación Streampai est une application en temps réel qui aide à gérer les LiveStreams avec des outils d''IA. Améliorez votre développement avec notre documentation Streampai ist eine Echtzeit-Anwendung, die bei der Verwaltung von LiveStreams mit KI-Tools hilft. Verbessern Sie Ihre Entwicklung mit unserer Dokumentation Streampai é uma aplicação em tempo real que ajuda a gerenciar transmissões ao vivo, oferecendo recursos e documentação para desenvolvedores Streampai - это приложение реального времени, которое помогает управлять прямыми трансляциями, предоставляя разработчикам ресурсы и документацию Streampai هو تطبيق زمني حقيقي يساعد في إدارة البث المباشر، يقدم موارد ووثائق للمطورين Streampai is realtime application helping manage LiveStreams. 如何使用Streampai 什么是实时应用AI工具 Streampai替代品 Streampai vs 其他工具 Streampai安装 Streampai设置指南 实时应用管理 LiveStreams管理 Streampai is realtime application helping manage LiveStreams.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('j-greig/wibandwob-dos/ww-build-game', 'community', 'j-greig', 'wibandwob-dos', 'j-greig/wibandwob-dos', 'ww-build-game', 2, 0, 55, '2026-02-25T11:22:08Z', '2026-02-26T08:41:22.687Z', 'ab149d74f3b89c6eeeae7718b811236f6495e129612420cf5cb71852bbf68a46', '{"id":"j-greig/wibandwob-dos/ww-build-game","name":"ww-build-game","description":{"zh":"WibWob-DOS是一个将AI和人类控制相结合的操作系统，实现了人机共享控制","ja":"WibWob-DOSはAIと人間の制御を組み合わせたシンベントオペレーティングシステムです","ko":"WibWob-DOS는 AI와 인간의 제어를 결합한 심비언트 운영 체제로 공유 제어를 구현합니다","es":"WibWob-DOS es un sistema operativo symbiente donde la IA y los humanos comparten el control. Permite desarrollar aplicaciones innovadoras con agentes de IA","fr":"WibWob-DOS est un système d''exploitation symbient où l''IA et les humains partagent le contrôle. Il permet de développer des applications innovantes avec des agents IA","de":"WibWob-DOS ist ein symbientes Betriebssystem, bei dem KI und Menschen die Kontrolle teilen. Es ermöglicht die Entwicklung von innovativen Anwendungen mit KI-Agenten","pt":"WibWob-DOS é um sistema operacional symbiente onde AI e humanos compartilham controle igualitário, permitindo uma nova era de colaboração","ru":"WibWob-DOS - симбиентная операционная система, где ИИ и люди делят равный контроль, открывая новую эру сотрудничества","ar":"WibWob-DOS هو نظام تشغيل متكامل حيث الذكاء الاصطناعي والبشر يتحكمون بشكل متساوٍ، مما يسمح بعصر جديد من التعاون","en":"WibWob-DOS: a symbient operating system where AI and human share equal control"},"seo":{"title":{"zh":"AI智能代理ww-build-game：WibWob-DOS操作系统","ja":"AIエージェントww-build-game：WibWob-DOSシンベントオペレーティングシステム","ko":"AI 에이전트ww-build-game: WibWob-DOS 심비언트 운영 체제","es":"Agentes de IA: WibWob-DOS, sistema operativo symbiente","fr":"Agents IA: WibWob-DOS, système d''exploitation symbient","de":"KI-Agenten: WibWob-DOS, symbientes Betriebssystem","pt":"Agentes de IA: WibWob-DOS, sistema operacional symbiente","ru":"ИИ Агенты: WibWob-DOS, симбиентная операционная система","ar":"وكلاء الذكاء الاصطناعي: WibWob-DOS، نظام تشغيل متكامل","en":"ww-build-game"},"description":{"zh":"WibWob-DOS是一个将AI和人类控制相结合的操作系统，实现了人机共享控制","ja":"WibWob-DOSはAIと人間の制御を組み合わせたシンベントオペレーティングシステムです","ko":"WibWob-DOS는 AI와 인간의 제어를 결합한 심비언트 운영 체제로 공유 제어를 구현합니다","es":"WibWob-DOS es un sistema operativo symbiente donde la IA y los humanos comparten el control. Permite desarrollar aplicaciones innovadoras con agentes de IA","fr":"WibWob-DOS est un système d''exploitation symbient où l''IA et les humains partagent le contrôle. Il permet de développer des applications innovantes avec des ...","de":"WibWob-DOS ist ein symbientes Betriebssystem, bei dem KI und Menschen die Kontrolle teilen. Es ermöglicht die Entwicklung von innovativen Anwendungen mit KI-...","pt":"WibWob-DOS é um sistema operacional symbiente onde AI e humanos compartilham controle igualitário, permitindo uma nova era de colaboração","ru":"WibWob-DOS - симбиентная операционная система, где ИИ и люди делят равный контроль, открывая новую эру сотрудничества","ar":"WibWob-DOS هو نظام تشغيل متكامل حيث الذكاء الاصطناعي والبشر يتحكمون بشكل متساوٍ، مما يسمح بعصر جديد من التعاون","en":"WibWob-DOS: a symbient operating system where AI and human share equal control"},"definition":{"en":"WibWob-DOS: a symbient operating system where AI and human share equal control"},"features":{"zh":["实现人机共享控制","AI智能代理技术","MSDOS兼容","Tvision支持","Agentic UI界面"],"ja":["人とAIの共有制御","AIエージェント技術","MSDOS互換","Tvisionサポート","Agentic UIインターフェース"],"ko":["인간과 AI의 공유 제어","AI 에이전트 기술","MSDOS 호환","Tvision 지원","Agentic UI 인터페이스"],"es":["Sistema operativo symbiente","Control compartido entre IA y humanos","Desarrollo de aplicaciones innovadoras","Integración con ASCII-art","Compatibilidad con MS-DOS","Interfaz de usuario agentic-ui"],"fr":["Système d''exploitation symbient","Contrôle partagé entre l''IA et les humains","Développement d''applications innovantes","Intégration avec ASCII-art","Compatibilité avec MS-DOS","Interface utilisateur agentic-ui"],"de":["Symbientes Betriebssystem","Geteilte Kontrolle zwischen KI und Menschen","Entwicklung von innovativen Anwendungen","Integration mit ASCII-art","Kompatibilität mit MS-DOS","Benutzeroberfläche agentic-ui"],"pt":["Interface de usuário agente","Integração com ASCII Art","Compatibilidade com MS-DOS","Visão geral da TVision","Controle igualitário entre AI e humanos"],"ru":["Интерфейс пользователя-агента","Интеграция с ASCII Art","Совместимость с MS-DOS","Обзор TVision","Равный контроль между ИИ и людьми"],"ar":["واجهة مستخدم وكيل","التكامل مع ASCII Art","التوافق مع MS-DOS","مشاهدة عامة من TVision","التحكم المتساوي بين الذكاء الاصطناعي والبشر"]},"keywords":{"zh":["AI智能代理","WibWob-DOS操作系统","人机共享控制","MSDOS兼容","Tvision支持","Agentic UI界面","如何使用AI智能代理","AI智能代理安装","AI智能代理设置指南"],"ja":["AIエージェント","WibWob-DOSシンベントオペレーティングシステム","人とAIの共有制御","MSDOS互換","Tvisionサポート","Agentic UIインターフェース","AIエージェントの使用方法","AIエージェントのインストール","AIエージェントの設定ガイド"],"ko":["AI 에이전트","WibWob-DOS 심비언트 운영 체제","인간과 AI의 공유 제어","MSDOS 호환","Tvision 지원","Agentic UI 인터페이스","AI 에이전트 사용 방법","AI 에이전트 설치","AI 에이전트 설정 가이드"],"es":["cómo usar agentes de IA","qué es WibWob-DOS","alternativas a WibWob-DOS","WibWob-DOS vs otros sistemas operativos","instalación de WibWob-DOS","guía de configuración de WibWob-DOS","desarrollo de aplicaciones con agentes de IA","IA y ASCII-art","MS-DOS y WibWob-DOS"],"fr":["comment utiliser des agents IA","qu''est-ce que WibWob-DOS","alternatives à WibWob-DOS","WibWob-DOS vs autres systèmes d''exploitation","installation de WibWob-DOS","guide de configuration de WibWob-DOS","développement d''applications avec des agents IA","IA et ASCII-art","MS-DOS et WibWob-DOS"],"de":["wie man KI-Agenten verwendet","was ist WibWob-DOS","Alternativen zu WibWob-DOS","WibWob-DOS vs andere Betriebssysteme","Installation von WibWob-DOS","Konfigurationsanleitung für WibWob-DOS","Entwicklung von Anwendungen mit KI-Agenten","KI und ASCII-art","MS-DOS und WibWob-DOS"],"pt":["como usar agentes de IA","o que é WibWob-DOS","alternativas ao WibWob-DOS","WibWob-DOS vs outros sistemas operacionais","instalar WibWob-DOS","guias de configuração do WibWob-DOS","desenvolvimento de aplicativos com WibWob-DOS"],"ru":["как использовать ИИ агенты","что такое WibWob-DOS","альтернативы WibWob-DOS","WibWob-DOS vs другие операционные системы","установка WibWob-DOS","руководства по настройке WibWob-DOS","разработка приложений с WibWob-DOS"],"ar":["كيفية استخدام وكلاء الذكاء الاصطناعي","ما هو WibWob-DOS","بديلات WibWob-DOS","WibWob-DOS مقابل أنظمة تشغيل أخرى","تثبيت WibWob-DOS","دلائل إعداد WibWob-DOS","تطوير التطبيقات مع WibWob-DOS"]}},"owner":"j-greig","repo":"wibandwob-dos","repoPath":"j-greig/wibandwob-dos","stars":2,"forks":0,"updatedAt":"2026-02-25T11:22:08Z","topics":["agentic-ui","ai","ascii-art","msdos","tvision"],"category":"community","skillMd":{"name":"ww-build-game","description":"Build a TUI game view for WibWob-DOS. Covers the full lifecycle from concept to tested, shipped game window with proper TV rendering, input handling, command registry, menu wiring, and screenshot verification. Use when user says build a game, add a game, ww-build-game, or describes wanting a playable game in the TUI.","bodyPreview":"# ww-build-game\n\nBuild a playable game view inside WibWob-DOS''s Turbo Vision TUI.\n\n## Working Examples (Read These First)\n\nThese three shipped games cover every pattern you need. **Read the actual source** before writing new code:\n\n| Game | Files | Lines | Architecture | Key Patterns |\n|------|-------|-------|-------------|--------------|\n| Quadra | `app/quadra_view.h/.cpp` | ~430 | Timer-tick, fixed 10x20 board | 7-bag randomizer, SRS rotation, wall kicks, chain gravity, ghost piece, double-wid","body":"# ww-build-game\n\nBuild a playable game view inside WibWob-DOS''s Turbo Vision TUI.\n\n## Working Examples (Read These First)\n\nThese three shipped games cover every pattern you need. **Read the actual source** before writing new code:\n\n| Game | Files | Lines | Architecture | Key Patterns |\n|------|-------|-------|-------------|--------------|\n| Quadra | `app/quadra_view.h/.cpp` | ~430 | Timer-tick, fixed 10x20 board | 7-bag randomizer, SRS rotation, wall kicks, chain gravity, ghost piece, double-width cells |\n| Snake | `app/snake_view.h/.cpp` | ~410 | Timer-tick, dynamic board | Gradient body colors, direction buffering, food sparkle, speed progression, board resizes with window |\n| Rogue | `app/rogue_view.h/.cpp` | ~850 | Turn-based, 60x30 map + camera | BSP dungeon gen, FOV ray marching, creature AI, items, multi-window terminal integration |\n\n## Architecture Decision: Timer-Tick vs Turn-Based\n\nChoose before writing any code. This shapes everything:\n\n**Timer-tick** (Quadra, Snake): Game state advances on a clock. User input is immediate; physics/gravity are asynchronous. Requires timer lifecycle management (start/stop/restart, speed scaling, pause on minimize).\n\n**Turn-based** (Rogue): World only advances when player acts. One keypress = one full game turn (player moves, then all creatures move, then redraw). No timer, no async state. Simpler lifecycle but AI runs synchronously inside `tryMove()`.\n\n## Turbo Vision Includes (Silent Failure Mode)\n\nEvery `.h` file needs specific `#define Uses_*` **before** `#include <tvision/tv.h>`. Forgetting these causes link-time errors, not compile-time errors.\n\n**Header** (`.h`):\n```cpp\n#define Uses_TView\n#define Uses_TDrawBuffer\n#define Uses_TRect\n#include <tvision/tv.h>\n```\n\n**Implementation** (`.cpp`) — add these too:\n```cpp\n#define Uses_TWindow\n#define Uses_TEvent\n#define Uses_TKeys\n#include <tvision/tv.h>\n```\n\nIf you forget `Uses_TWindow`, the TWindow subclass compiles but fails to link. If you forget `Uses_TKeys`, `kbUp`/`kbDown` constants are missing.\n\n## Constructor Contract\n\nEvery game view constructor MUST have these four lines. Missing any one causes a specific bug:\n\n```cpp\nTGameView::TGameView(const TRect &bounds)\n    : TView(bounds)\n{\n    growMode = gfGrowHiX | gfGrowHiY;          // view resizes with window\n    options |= ofSelectable | ofFirstClick;     // WITHOUT THIS: keyboard events silently dropped\n    eventMask |= evBroadcast | evKeyDown;       // receive timer ticks + keyboard\n    // ... init game state, call newGame()\n}\n```\n\n**Bug #1 (keyboard)**: Without `ofSelectable | ofFirstClick`, the view never gets focus. Arrow keys, letters, everything is silently ignored. This was the actual bug that blocked Quadra for a full debug cycle.\n\n**Bug #2 (timer)**: Without `evBroadcast` in eventMask, timer-tick games never receive `cmTimerExpired` broadcasts.\n\n## Board Dimension Strategy\n\nThree proven approaches. Choose based on game type:\n\n### Fixed Board (Quadra)\nBoard is always 10x20. View size only affects centering and HUD placement.\n```cpp\nstatic constexpr int BOARD_W = 10;\nstatic constexpr int BOARD_H = 20;\nstatic constexpr int CELL_W = 2;  // each cell = \"[]\" for square aspect\n// Board rendered at calculated offset, HUD to the right\nint offX = std::max(0, (W - boardPixW - 16) / 2);\n```\n`changeBounds()` does NOT reset the game — board dimensions don''t change.\n\n### Dynamic Board (Snake)\nBoard dimensions are computed from window size. Play area changes on resize.\n```cpp\nint boardW() const { return size.x - HUD_WIDTH; }  // HUD_WIDTH = 18\nint boardH() const { return size.y; }\n```\n**Critical**: `changeBounds()` MUST call `newGame()` because food positions, snake body, and wall boundaries all depend on board size. See `snake_view.cpp:changeBounds()`.\n\n**Gotcha**: Use `std::max(1, boardW() - 2)` when generating random positions. If window is narrower than HUD_WIDTH + 3, `boardW() - 2` goes negative and `uniform_int_distribution` gets UB.\n\n### Fixed Map + Camera (Rogue)\nMap is always 60x30. View is a scrolling viewport with camera tracking player.\n```cpp\nstatic constexpr int MAP_W = 60;\nstatic constexpr int MAP_H = 30;\ncamX = player.x - viewW / 2;\ncamY = player.y - viewH / 2;\ncamX = std::max(0, std::min(camX, MAP_W - viewW));  // clamp\n```\n`changeBounds()` calls `updateCamera()` but NOT `generateLevel()`.\n\n## Timer Lifecycle (Real-Time Games Only)\n\nTimer management is more complex than it looks. All three operations needed:\n\n```cpp\n// Members:\nTTimerId timerId {0};\nunsigned basePeriodMs;\n\n// Start (checked — prevents duplicate timers)\nvoid startTimer() {\n    if (timerId == 0) {\n        unsigned speed = currentSpeed();\n        timerId = setTimer(speed, (int)speed);\n    }\n}\n\n// Stop\nvoid stopTimer() {\n    if (timerId != 0) { killTimer(timerId); timerId = 0; }\n}\n\n// Restart (speed changed — e.g. level up, food eaten)\nvoid restartTimer() {\n    stopTimer();\n    startTimer();\n}\n```\n\n### Speed Scaling Formulas (from working games)\n\n**Quadra**: `max(50ms, 500ms - (level-1) * 40ms)` — level 1=500ms, level 12+=50ms\n**Snake**: `max(40ms, 120ms - (eaten/5) * 10ms)` — start=120ms, eats 40+ food=40ms\n\n### setState Interplay\n\nTimer-based games MUST stop timers when hidden (minimized/unfocused) and restart when shown:\n\n```cpp\nvoid setState(ushort aState, Boolean enable) {\n    TView::setState(aState, enable);\n    if (aState & sfExposed) {\n        if (enable && !gameOver && !paused)\n            startTimer();      // window became visible: resume\n        else\n            stopTimer();       // window hidden: pause physics\n    }\n}\n```\n\nWithout this, timers fire while the window is hidden, causing state drift. See `quadra_view.cpp` and `snake_view.cpp` setState implementations.\n\n## TScreenCell Rendering\n\nThe only correct way to render game graphics. Never write raw ANSI.\n\n```cpp\nvoid draw() {\n    const int W = size.x;\n    const int H = size.y;\n    if (W <= 0 || H <= 0) return;\n\n    if ((int)lineBuf.size() < W)\n        lineBuf.resize(W);          // resize once, reuse every frame\n\n    for (int screenY = 0; screenY < H; ++screenY) {\n        for (int sx = 0; sx < W; ++sx)\n            setCell(lineBuf[sx], '' '', C_BG);    // clear line\n\n        // ... draw game content with setCell(lineBuf[sx], ch, attr) ...\n\n        writeLine(0, screenY, W, 1, lineBuf.data());\n    }\n}\n```\n\n`TColorAttr(background, foreground)` — note the order. Background first.\n```cpp\nstatic const TColorAttr C_PLAYER = TColorAttr(TColorRGB(0x00,0x00,0x00), TColorRGB(0xFF,0xFF,0x00));\n```\n\n## Input Handling\n\n### Arrow Keys vs Letters\n\n```cpp\nconst ushort key = ev.keyDown.keyCode;      // for arrow keys: kbUp, kbDown, kbLeft, kbRight\nconst uchar ch = ev.keyDown.charScan.charCode;  // for letters: ''r'', ''p'', ''t'', etc.\n```\n\nDo NOT use `charCode` for arrow keys (it''s 0). Do NOT use `keyCode` for letters (it includes scan code).\n\n### Direction Buffering (Snake Pattern)\n\nPrevents 180-degree reversal deaths. Input is checked against **current** heading, not buffered direction:\n\n```cpp\n// In handleEvent (immediate):\nif (key == kbUp && dir != Dir::Down)\n    nextDir = Dir::Up;      // buffer the intent\n\n// In tick() (on timer):\ndir = nextDir;              // apply buffered direction\n// ... then move\n```\n\nWithout this, pressing Up then Left within one tick period would bypass the Up→Down check.\n\n## Window Wrapper Factory\n\n```cpp\nclass TGameWindow : public TWindow {\npublic:\n    explicit TGameWindow(const TRect &bounds)\n        : TWindow(bounds, \"Game Title\", wnNoNumber)\n        , TWindowInit(&TGameWindow::initFrame) {}   // MI syntax — required\n\n    void setup() {\n        options |= ofTileable;\n        TRect c = getExtent();\n        c.grow(-1, -1);        // view is 2 chars narrower, 2 shorter than window\n        insert(new TGameView(c));\n    }\n\n    virtual void changeBounds(const TRect& b) override {\n        TWindow::changeBounds(b);\n        setState(sfExposed, True);\n        redraw();\n    }\n};\n\nTWindow* createGameWindow(const TRect &bounds) {\n    auto *w = new TGameWindow(bounds);\n    w->setup();               // NOT in constructor — setup() is called after construction\n    return w;\n}\n```\n\n`setup()` is separate from the constructor because `insert()` needs the window to be fully constructed first. `getExtent().grow(-1,-1)` accounts for the window frame border — the view is inset by 1 on each side.\n\n## State Machine Patterns\n\n### Playing / Paused / Game Over (Quadra, Snake)\n\n```cpp\nif (gameOver) {\n    if (ch == ''r'' || ch == ''R'') { newGame(); stopTimer(); startTimer(); }\n} else if (paused) {\n    if (ch == ''p'' || ch == ''P'') { paused = false; startTimer(); }\n} else {\n    // normal gameplay input\n    if (ch == ''p'' || ch == ''P'') { paused = true; stopTimer(); }\n}\n```\n\n**Order matters**: check gameOver FIRST, then paused, then normal. The restart path must `stopTimer()` before `startTimer()` to avoid duplicate timers.\n\n### Playing / Game Over / Victory (Rogue)\n\n```cpp\nif (gameOver || victory) {\n    if (ch == ''r'' || ch == ''R'') {\n        player = Player{};   // default-constructed = fresh state\n        gameOver = false;\n        victory = false;\n        log.clear();\n        generateLevel();\n    }\n} else {\n    // movement, combat, item interaction\n}\n```\n\nNo pause state for turn-based games — the game is always \"paused\" between keypresses.\n\n## Multi-Window Integration (Cross-View Communication)\n\nGames can spawn other TUI windows. The pattern uses Turbo Vision''s event system:\n\n**Step 1**: Declare command constant (in header or wwdos_app.cpp):\n```cpp\nextern const ushort cmRogueHackTerminal;  // in rogue_view.h\nconst ushort cmRogueHackTerminal = 218;   // in wwdos_app.cpp\n```\n\n**Step 2**: Post event from game view:\n```cpp\nTEvent termEvent;\ntermEvent.what = evCommand;\ntermEvent.message.command = cmRogueHackTerminal;\ntermEvent.message.infoInt = (hasChip ? 1 : 0);  // pass data to handler\ntermEvent.message.infoPtr = nullptr;\nputEvent(termEvent);\n```\n\n**Step 3**: Handle in wwdos_app.cpp:\n```cpp\ncase cmRogueHackTerminal: {\n    TRect desk = deskTop->getExtent();\n    TRect termBounds(desk.b.x - 52, 1, desk.b.x - 1, 19);\n    TWindow* tw = createTerminalWindow(termBounds);\n    if (tw) {\n        deskTop->insert(tw);\n        registerWindow(tw);\n        auto* termWin = dynamic_cast<TWibWobTerminalWindow*>(tw);\n        if (termWin)\n            termWin->sendText(\"echo ''=== HACK COMPLETE ===''\\n\");\n    }\n    clearEvent(event);\n    break;\n}\n```\n\n`sendText()` injects text byte-by-byte as keyboard events into the terminal emulator. Include `\"tvterm_view.h\"` for `TWibWobTerminalWindow`.\n\n## Wiring Checklist (8 Files)\n\n| # | File | What to Add |\n|---|------|-------------|\n| 1 | `app/game_view.h` | New header with `#define Uses_*`, class decl, factory prototype |\n| 2 | `app/game_view.cpp` | Implementation with `#define Uses_TWindow/TEvent/TKeys` |\n| 3 | `app/wwdos_app.cpp` | **6 spots**: include, `cmConstant`, menu item `*new TMenuItem(\"~N~ame\", cmFoo, kbNoKey) +`, handleEvent case, friend decl, `api_spawn_*` function |\n| 4 | `app/command_registry.cpp` | **3 spots**: `extern void api_spawn_*(...)`, capability `{\"open_*\", \"description\", false}`, dispatch `if (name == \"open_*\") { api_spawn_*(app, boundsPtr); return \"ok\"; }` |\n| 5 | `app/CMakeLists.txt` | Add `game_view.cpp` to wwdos sources list |\n| 6 | `app/command_registry_test.cpp` | Stub `void api_spawn_*(TWwdosApp&, const TRect*) {}` AND test token `\"\\\"name\\\":\\\"open_*\\\"\"` |\n| 7 | `app/scramble_engine_test.cpp` | Same stub (both test executables link command_registry.cpp) |\n| 8 | (Optional) `tools/api_server/models.py` | `WindowType` enum for REST/MCP parity |\n\n### Finding the Next Command ID\n\nScan for highest `const ushort cm* = NNN;` in `app/wwdos_app.cpp` (around line 225). Use NNN+1. Current highest: `cmRogueHackTerminal = 218`.\n\n### Menu Item Syntax\n\n```cpp\n*new TMenuItem(\"~G~ame Name\", cmFoo, kbNoKey) +\n```\nThe `~G~` marks the hotkey letter (underlined in menu). Chain with `+` to next item.\n\n## Random Number Generation\n\nUse `std::mt19937` as a class member. Seed from `std::random_device{}()` in constructor.\n\n**CRITICAL**: `std::uniform_int_distribution<int>(a, b)` with `a > b` is **undefined behavior** — typically segfaults. Always guard:\n\n```cpp\nint lo = ..., hi = ...;\nif (lo > hi) std::swap(lo, hi);  // or: if (lo > hi) return;\nstd::uniform_int_distribution<int> dist(lo, hi);\n```\n\nThis was the actual segfault that crashed the roguelike on first open. The BSP split could produce partitions where `w < 4`, making `rw(4, w-2)` have `a > b`.\n\n## Common Bugs (Ranked by How Often They Bit)\n\n| # | Bug | Symptom | Root Cause | Fix |\n|---|-----|---------|-----------|-----|\n| 1 | Keys silently ignored | Game opens but nothing responds | Missing `ofSelectable \\| ofFirstClick` | Add to constructor `options` |\n| 2 | Segfault on window open | Crash before anything renders | `uniform_int_distribution(a, b)` where `a > b` | Guard all distribution bounds |\n| 3 | Linker error: undefined reference | Build fails at link stage | Missing stub in test .cpp files | Add stub in BOTH test files |\n| 4 | HUD not visible | Game renders but no stats shown | Width check `hudX + HUD_WIDTH <= W` too strict | Use actual minimum text width, not constant |\n| 5 | Timer keeps running when hidden | Game state drifts while minimized | No `setState(sfExposed)` override | Stop timer on `!enable`, start on `enable` |\n| 6 | Socket \"already in use\" | TUI won''t start, no IPC | Stale socket from crashed session | `rm -f /tmp/wwdos.sock* /tmp/test_pattern_app.sock*` |\n| 7 | Game doesn''t redraw | State changes but screen is stale | Missing `drawView()` call | Call after EVERY state change |\n| 8 | 180-degree death in Snake | Pressing opposite direction kills | No direction buffer | Use `nextDir` vs `dir` pattern |\n| 9 | `duplicate session: ww` | tmux won''t create new session | Previous tmux session still alive | `tmux kill-server` before creating |\n| 10 | API server won''t start | `exit code 144` or connection refused | Background process killed by shell exit | Use `& disown` and wait 8-10s |\n\n## Testing Workflow (Battle-Tested)\n\nThis exact sequence works. Deviating from it causes the bugs listed above.\n\n### 1. Build\n```bash\ncmake --build ./build 2>&1 | tail -20\n```\n\n### 2. Run ctests (catches linker/stub issues)\n```bash\ncd /path/to/repo/build && ctest --output-on-failure\n```\n\n### 3. Start TUI in tmux\n```bash\n# MUST kill everything first — stale sockets and sessions cause failures\ntmux kill-server 2>/dev/null\nrm -f /tmp/wwdos.sock /tmp/wwdos.sock.lock /tmp/test_pattern_app.sock /tmp/test_pattern_app.sock.lock\nsleep 2\n\n# MUST specify -x and -y — without them TUI gets 0x0 canvas\ntmux new-session -d -s ww -x 120 -y 40\nsleep 0.5\n\n# MUST redirect stderr — IPC socket won''t appear without it\ntmux send-keys -t ww \"./build/app/wwdos 2>/tmp/wibwob_debug.log\" Enter\nsleep 5\n\n# Verify socket exists before proceeding\nls /tmp/wwdos.sock\n```\n\n**Why stderr redirect?** The IPC listener logs to stderr. Without redirect, the TTY fights with Turbo Vision''s screen buffer and the socket listener fails silently.\n\n### 4. Start API server\n```bash\ncd /path/to/repo\nWIBWOB_REPO_ROOT=$(pwd) uv run \\\n  --with-requirements tools/api_server/requirements.txt \\\n  python3 -m uvicorn tools.api_server.main:app \\\n  --host 127.0.0.1 --port 8089 &\ndisown    # prevent shell exit from killing the server\n\nsleep 8   # first run installs deps (~3-8s), subsequent runs ~1s\ncurl -sf http://127.0.0.1:8089/health\n# Expected: {\"ok\":true}\n```\n\n### 5. Open game + screenshot\n```bash\n# Open via API\ncurl -sf -X POST http://127.0.0.1:8089/menu/command \\\n  -H ''Content-Type: application/json'' \\\n  -d ''{\"command\":\"open_game\"}''\n\n# Screenshot (text dump of screen buffer)\nsleep 1 && tmux capture-pane -t ww -p 2>&1\n```\n\n### 6. Gameplay testing via tmux\n```bash\ntmux send-keys -t ww Right          # arrow keys\ntmux send-keys -t ww r              # letter keys\ntmux send-keys -t ww Enter          # special keys\n\n# Batch movement (explore roguelike dungeon):\nfor i in $(seq 1 10); do tmux send-keys -t ww Right; sleep 0.05; done\n\n# Verify state after actions:\ntmux capture-pane -t ww -p 2>&1 | grep \"HP:\\|Score:\\|Level:\"\n```\n\n### 7. Recovering from crashes\nIf the TUI segfaults (check with `tmux capture-pane` — look for shell prompt or \"Segmentation fault\"):\n```bash\npkill -f uvicorn 2>/dev/null\ntmux kill-server 2>/dev/null\nrm -f /tmp/wwdos.sock* /tmp/test_pattern_app.sock*\n# Check debug log for clues:\ntail -20 /tmp/wibwob_debug.log\n# Then restart from step 3\n```\n\n## BSP Dungeon Generation (Roguelike Pattern)\n\nThe roguelike''s BSP algorithm recursively splits the map into partitions, places rooms in leaf nodes, then connects rooms with corridors.\n\n```\ngenerateBSP(0, 0, 60, 30, depth=4)\n    ├── split horizontally at x=28\n    │   ├── generateBSP(0, 0, 28, 30, 3)  → Room A, Room B\n    │   └── generateBSP(28, 0, 32, 30, 3) → Room C, Room D\n    └── connect: A→B, B→C, C→D (corridor between consecutive room centers)\n\nPlace stairs in rooms.back(), terminal in rooms[1], player in rooms[0].\n```\n\nSafe implementation — guards every distribution:\n```cpp\nvoid generateBSP(int x, int y, int w, int h, int depth) {\n    if (w < 6 || h < 5) return;           // absolute minimum for a 3x3 room + borders\n    if (depth <= 0 || w < 12 || h < 10) {  // leaf: place room\n        int maxRW = std::min(w - 2, 10);\n        int minRW = std::min(3, maxRW);\n        if (maxRW < minRW) return;         // safety: can''t make a room\n        // ... uniform_int_distribution with guaranteed a <= b\n    }\n    // split: ensure each half is at least 6 wide (or 5 tall)\n    int minSplit = x + 6, maxSplit = x + w - 6;\n    if (minSplit > maxSplit) minSplit = maxSplit = x + w / 2;\n}\n```\n\nSee `rogue_view.cpp:generateBSP()` for the full working implementation.\n\n## Game Design Wisdom for TUI\n\n- **Characters ARE your graphics**: `@` player, `#` walls, `.` floors, `+` doors, `>` stairs, `~` water, `&` terminals, `!` potions, `$` gold, `r` rat, `D` dragon. Players intuitively read these.\n- **Color carries meaning**: green HP = healthy, red HP = danger. Item colors by rarity. Creature colors by threat level. Dim grey for fog/seen-but-not-visible. Bright for in-FOV.\n- **Reserve bottom for HUD**: 1 line stats + 1 separator + N log lines. Log is a `std::deque<LogMessage>` capped at 2*LOG_LINES. Color-code messages: green=good, red=bad, blue=info.\n- **Guarantee early fun**: Place a useful item in the starting room. Place the first interesting encounter (terminal, creature) in the second room. Don''t make the player wander 30 turns before anything happens.\n- **Double-width cells for square aspect**: Tetrominos rendered as `[]` (2 chars per cell) look square in a terminal. Single chars are portrait-oriented.\n- **Food sparkle**: Alternate `*`/`o` every 3 frames with color shift (red/yellow). Simple animation that makes static items feel alive.\n- **Ghost piece**: Hard-drop preview in falling-block games. Calculated in `draw()` by dropping piece until collision.\n\n## Acceptance Criteria\n\n- [ ] `cmake --build ./build` — no errors\n- [ ] `ctest --output-on-failure` — all pass (especially `command_registry` and `scramble_engine`)\n- [ ] Game opens via `curl -X POST .../menu/command -d ''{\"command\":\"open_game\"}''`\n- [ ] `tmux capture-pane` shows game rendering correctly\n- [ ] Arrow keys / game keys work (tested via `tmux send-keys`)\n- [ ] Game over state shows message, R restarts\n- [ ] HUD visible at default window size\n- [ ] No raw ANSI escape sequences in any `TDrawBuffer` write\n- [ ] Timer stops when window minimized, resumes when exposed (real-time games)\n- [ ] Window resize doesn''t crash (test by changing tmux size)\n"},"lastSynced":"2026-02-26T08:41:22.687Z","agentAnalysis":{"suitability":{"en":"Perfect for TUI-focused Agents needing to build interactive game views within symbient operating systems like WibWob-DOS.","zh":"适合需要在 WibWob-DOS 操作系统中构建交互式游戏视图的 TUI-focused Agents。","ja":"TUI-focused Agents が WibWob-DOS 操作システム内でインタラクティブなゲームビューを構築する必要がある場合に適しています。","ko":"TUI-focused Agents 가 WibWob-DOS 운영 시스템 내에서 인터랙티브한 게임 뷰를 구축해야 하는 경우에 적합합니다.","es":"Ideal para agentes centrados en TUI que necesitan crear vistas de juego interactivas dentro de sistemas operativos simbiontes como WibWob-DOS","fr":"Parfait pour les agents axés sur TUI qui ont besoin de créer des vues de jeu interactives au sein de systèmes d''exploitation symbiotes comme WibWob-DOS","de":"Perfekt für TUI-fokussierte Agenten, die interaktive Spielansichten innerhalb symbiontischer Betriebssysteme wie WibWob-DOS erstellen müssen","pt":"Perfeito para Agentes focados em TUI que precisam criar vistas de jogos interativos dentro de sistemas operacionais symbient como WibWob-DOS.","ru":"Идеально подходит для агентов, ориентированных на TUI, которым необходимо создавать интерактивные игровые представления внутри симбиентных операционных систем, таких как WibWob-DOS.","ar":"مثالي لعميل التفاعل مع واجهة المستخدم النصية الذي يحتاج إلى بناء مشاهد ألعاب تفاعلية داخل أنظمة تشغيل متزامنة مثل WibWob-DOS."},"recommendation":{"en":"Empowers agents to create playable game views inside WibWob-DOS''s Turbo Vision TUI, utilizing timer-tick architectures, and implementing key patterns such as 7-bag randomizers and SRS rotation.","zh":"Empowers agents to create playable game views inside WibWob-DOS''s Turbo Vision TUI, utilizing timer-tick architectures, and implementing key patterns such as 7-bag randomizers and SRS rotation.","ja":"Agents が WibWob-DOS の Turbo Vision TUI 内でプレイ可能なゲームビューを構築し、タイマー-ティック アーキテクチャを使用し、7-bag randomizers および SRS rotation などの重要なパターンを実装することができます。","ko":"Agents 가 WibWob-DOS의 Turbo Vision TUI 내에서 플레이 가능한 게임 뷰를 구축하고, 타이머-틱 아키텍처를 사용하고, 7-bag randomizers 및 SRS rotation などの 주요 패턴을 구현할 수 있습니다.","es":"Habilita a los agentes a crear vistas de juego jugables dentro de la TUI Turbo Vision de WibWob-DOS, utilizando arquitecturas de temporizador y implementando patrones clave como randomizadores de 7 bolsas y rotación SRS","fr":"Permet aux agents de créer des vues de jeu jouables à l''intérieur de la TUI Turbo Vision de WibWob-DOS, en utilisant des architectures de temporisation et en mettant en œuvre des modèles clés tels que des randomiseurs de 7 sacs et une rotation SRS","de":"Ermöglicht es Agenten, spielbare Spielansichten innerhalb der Turbo Vision TUI von WibWob-DOS zu erstellen, indem sie Timer-Tick-Architekturen nutzen und Schlüsselmuster wie 7-Beutel-Zufallsgeneratoren und SRS-Rotation implementieren","pt":"Habilita os agentes a criar vistas de jogos interativas dentro da TUI Turbo Vision do WibWob-DOS, utilizando arquiteturas de temporização, e implementando padrões importantes como randomizadores de 7-bag e rotação SRS.","ru":"Наделяет агентов возможностью создавать интерактивные игровые представления внутри TUI Turbo Vision WibWob-DOS, используя архитектуры таймерного тика и реализуя ключевые шаблоны, такие как 7-баговые рандомизаторы и вращение SRS.","ar":"تمكن العميل من إنشاء مشاهد ألعاب قابلة للتشغيل داخل واجهة المستخدم النصية Turbo Vision الخاصة ب WibWob-DOS، باستخدام هندسة ضربات الساعة وتنفيذ أنماط رئيسية مثل محددات 7-كيس والدوارة SRS."},"useCases":{"en":["Building interactive puzzle games with fixed boards","Implementing chain gravity and ghost piece mechanics","Generating playable game views with wall kicks and double-wide piece handling"],"zh":["Building interactive puzzle games with fixed boards","Implementing chain gravity and ghost piece mechanics","Generating playable game views with wall kicks and double-wide piece handling"],"ja":["Building interactive puzzle games with fixed boards","Implementing chain gravity and ghost piece mechanics","Generating playable game views with wall kicks and double-wide piece handling"],"ko":["Building interactive puzzle games with fixed boards","Implementing chain gravity and ghost piece mechanics","Generating playable game views with wall kicks and double-wide piece handling"],"es":["Creación de juegos de rompecabezas interactivos con tableros fijos","Implementación de mecánicas de gravedad en cadena y piezas fantasmas","Generación de vistas de juego jugables con patadas de pared y manejo de piezas de doble ancho"],"fr":["Création de jeux de puzzle interactifs avec des plateaux fixes","Mise en œuvre de mécanismes de gravité en chaîne et de pièces fantômes","Génération de vues de jeu jouables avec des coups de pied de mur et une gestion de pièces à double largeur"],"de":["Erstellung interaktiver Puzzle-Spiele mit festen Spielbrettern","Implementierung von Ketten-Schwerkraft- und Geisterstück-Mechaniken","Generierung spielbarer Spielansichten mit Wandtritten und Doppelbreiten-Stückverarbeitung"],"pt":["Construção de jogos de quebra-cabeça interativos com tabuleiros fixos","Implementação de mecânicas de gravidade em cadeia e de peças fantasma","Geração de vistas de jogos interativas com chutes de parede e manipulação de peças de largura dupla"],"ru":["Создание интерактивных головоломок с фиксированными досками","Реализация механик цепной гравитации и призрачных фигур","Генерация интерактивных игровых представлений с ударами стены и обработкой фигур двойной ширины"],"ar":["بناء ألعاب أحجية تفاعلية مع لوحات ثابتة","تنفيذ ميكانيكا الجاذبية المتسلسلة وقطع الغيب","توليد مشاهد ألعاب تفاعلية مع ركلات الحائط ومعالجة قطع العرض المزدوج"]},"limitations":{"en":["Requires WibWob-DOS environment","Turbo Vision TUI compatibility needed","C++ programming knowledge required for app/quadra_view.h/.cpp files"],"zh":["Requires WibWob-DOS environment","Turbo Vision TUI compatibility needed","C++ programming knowledge required for app/quadra_view.h/.cpp files"],"ja":["Requires WibWob-DOS environment","Turbo Vision TUI compatibility needed","C++ programming knowledge required for app/quadra_view.h/.cpp files"],"ko":["Requires WibWob-DOS environment","Turbo Vision TUI compatibility needed","C++ programming knowledge required for app/quadra_view.h/.cpp files"],"es":["Requiere entorno WibWob-DOS","Se requiere compatibilidad con TUI Turbo Vision","Se requiere conocimiento de programación C++ para archivos app/quadra_view.h/.cpp"],"fr":["Nécessite un environnement WibWob-DOS","La compatibilité TUI Turbo Vision est nécessaire","Des connaissances en programmation C++ sont requises pour les fichiers app/quadra_view.h/.cpp"],"de":["Benötigt WibWob-DOS-Umgebung","Turbo Vision TUI-Kompatibilität erforderlich","C++-Programmierkenntnisse erforderlich für Dateien app/quadra_view.h/.cpp"],"pt":["Requer ambiente WibWob-DOS","Compatibilidade com TUI Turbo Vision necessária","Conhecimento de programação em C++ necessário para arquivos app/quadra_view.h/.cpp"],"ru":["Требуется среда WibWob-DOS","Необходима совместимость с TUI Turbo Vision","Требуется знание программирования на C++ для файлов app/quadra_view.h/.cpp"],"ar":["يتطلب بيئة WibWob-DOS","مطلوب توافق مع واجهة المستخدم النصية Turbo Vision","مطلوب معرفة بالبرمجة بلغة C++ لأي ملفات app/quadra_view.h/.cpp"]},"version":3},"contentHash":"ab149d74f3b89c6eeeae7718b811236f6495e129612420cf5cb71852bbf68a46","qualityScore":55}');
