INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('brenordv/rust-pad/rust', 'rust', 'brenordv', 'rust-pad', 'community', 'rust brenordv rust-pad community gui notebook notepad notepad-plus-plus notes tools Rust跨平台记事本是Notepad++的克隆版，提供跨平台的笔记功能 Rustクロスプラットフォームメモ帳はNotepad++のクローン版、クロスプラットフォームのメモ機能を提供 Rust 크로스 플랫폼 메모장은 Notepad++의 클론 버전으로, 크로스 플랫폼의 메모 기능을 제공 Rust es una herramienta de notas de código abierto inspirada en Notepad++, diseñada para proporcionar una experiencia de escritura eficiente en múltiples plataformas Rust est un outil de notes open source inspiré de Notepad++, conçu pour offrir une expérience d''écriture efficace sur plusieurs plateformes Rust ist ein Open-Source-Notiztool inspiriert von Notepad++, entwickelt für eine effiziente Schreibweise auf mehreren Plattformen A ferramenta Rust é um notepad de código aberto inspirado no Notepad++, com funcionalidades de edição de texto avançadas ИИ Агент Rust - кроссплатформенный блокнот, вдохновленный Notepad++, с расширенными функциями редактирования текста أداة الرست هي محرر نصوص مفتوح المصدر مستوحى من برنامج Notepad++، مع ميزات تحرير متقدمة Cross-platform Notepad inspired by Notepad++ Rust跨平台记事本 Notepad++替代品 如何使用Rust记事本 Rust记事本安装 Rust记事本设置指南 跨平台笔记工具 Rust开发工具 笔记软件比较 Cross-platform Notepad inspired by Notepad++');
