INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bjeber/cc-md-search-cli/ccmds', 'ccmds', 'bjeber', 'cc-md-search-cli', 'community', 'ccmds bjeber cc-md-search-cli community ccmds是一个为AI代码助手设计的文档搜索CLI，帮助开发者提高代码编写效率 ccmdsは、AIコードアシスタント用のドキュメント検索CLIであり、開発者のコード作成効率を向上させる ccmds는 AI 코드 도우미를 위한 문서 검색 CLI로, 개발者の 코드 작성 효율을 높여줍니다 ccmds es una herramienta de búsqueda de documentación de línea de comandos diseñada para asistentes de codificación de IA, que facilita la búsqueda de información técnica ccmds est un outil de recherche de documentation en ligne de commande conçu pour les assistants de codage IA, qui facilite la recherche d''informations techniques ccmds ist ein Dokumentensuche-CLI-Tool, das für KI-Coding-Assistenten entwickelt wurde und die Suche nach technischen Informationen erleichtert O ccmds é uma ferramenta de busca de documentação CLI projetada para assistentes de codificação de IA, permitindo uma busca rápida e eficaz de informações ccmds - это поисковая документация CLI для ИИ Агентов, обеспечивающая быстрый и эффективный поиск информации ccmds هي أداة بحث الوثائق المصممة لمساعدي الترميز الاصطناعي، تمكن من البحث السريع والفعال عن المعلومات A documentation search CLI designed for AI coding assistants AI工具 代码编写助手 文档搜索CLI ccmds安装 ccmds使用教程 代码编写效率 AI代码助手 CLI工具 A documentation search CLI designed for AI coding assistants');
