INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cdeistopened/OpenEd-Vault/video-caption-creation', 'video-caption-creation', 'cdeistopened', 'OpenEd-Vault', 'community', 'video-caption-creation cdeistopened OpenEd-Vault community video-caption-creation技能使用AI技术创建视频字幕，提高开发效率 video-caption-creationスキルはAIエージェントを使用して動画字幕を作成し、開発効率を向上させる video-caption-creation 기능은 AI를 사용하여 비디오 자막을 생성하여 개발 효율성을 높입니다 My OpenEd Workspace ofrece herramientas de inteligencia artificial para la creación de subtítulos de video, mejorando la accesibilidad y la experiencia del usuario My OpenEd Workspace propose des outils d''intelligence artificielle pour la création de sous-titres de vidéo, améliorant l''accessibilité et l''expérience utilisateur My OpenEd Workspace bietet künstliche Intelligenz-Tools für die Erstellung von Videountertiteln, um die Zugänglichkeit und Benutzererfahrung zu verbessern O Workspace My OpenEd oferece uma solução inovadora para criação de legendas de vídeo com precisão, utilizando ferramentas de IA My OpenEd Workspace предоставляет инновационное решение для создания видеокапшенов с точностью, используя ИИ Агенты يعرض Workspace My OpenEd حلًا مبتكرًا لإنشاء Legends الفيديو بدقة، باستخدام أدوات الذكاء الاصطناعي My OpenEd Workspace 如何使用AI创建视频字幕 video-caption-creation技能介绍 AI视频字幕创建工具 My OpenEd Workspace教程 视频字幕创建技巧 AI开发工具 My OpenEd Workspace');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hotriluan/alkana_kpi/research', 'community', 'hotriluan', 'alkana_kpi', 'hotriluan/alkana_kpi', 'research', 0, 0, 55, '2026-03-04T13:07:01.697Z', '2026-03-04T13:36:47.447Z', 'd7eed88b8d795e30c8c17661998aeffc1246d8caac283f935f27a3382a1bc36b', '{"id":"hotriluan/alkana_kpi/research","name":"research","description":{"zh":"Alkana KPI应用的研究功能提供了数据分析和可视化的能力，帮助开发者提高效率","ja":"Alkana KPIアプリケーションの研究機能は、データ分析と可視化の機能を提供し、開発者の効率を向上させる","ko":"Alkana KPI 애플리케이션의 연구 기능은 데이터 분석 및 시각화를 제공하여 개발자의 효율성을 향상시킵니다","es":"El skill ''research'' es un agente de IA especializado en la aplicación Alkana KPI. Automatiza la recopilación, procesamiento y análisis de métricas clave para desarrolladores, ofreciendo insights accionables mediante APIs y scripts personalizables.","fr":"La compétence ''research'' est un agent IA spécialisé pour l''application Alkana KPI. Il automatise la collecte, le traitement et l''analyse des métriques clés pour les développeurs, fournissant des insights actionnables via des APIs et des scripts personnalisables.","de":"Die ''research''-Fähigkeit ist ein spezialisierter KI-Agent für die Alkana KPI-Anwendung. Er automatisiert die Erfassung, Verarbeitung und Analyse von Key Metrics für Entwickler und liefert actionable Insights über APIs und anpassbare Skripte.","pt":"A pesquisa da aplicação Alkana KPI é uma ferramenta de IA que ajuda no desenvolvimento de soluções com React, Python e Node.js","ru":"Исследование приложения Alkana KPI - это инструмент ИИ, который помогает в разработке решений с React, Python и Node.js","ar":"البحث في تطبيق Alkana KPI هو أداة ذكاء اصطناعي تساعد في تطوير حلول مع React و Python و Node.js","en":"Alkana KPI application"},"seo":{"title":{"zh":"AI智能工具：Alkana KPI 应用研究","ja":"AIエージェント：Alkana KPI アプリケーション研究","ko":"AI 에이전트: Alkana KPI 애플리케이션 연구","es":"Research AI Agent: Herramienta Alkana KP