INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('openai/openai-agents-python/pr-draft-summary', 'pr-draft-summary', 'openai', 'openai-agents-python', 'community', 'pr-draft-summary openai openai-agents-python community pr-draft-summary是一个轻量级、强大的多智能体工作流框架，用于提高开发效率 pr-draft-summaryは軽量で強力なマルチエージェントワークフローフレームワークです pr-draft-summary는 가벼우면서 강력한 멀티 에이전트 워크플로우 프레임워크입니다 pr-draft-summary es un framework ligero y poderoso para multiagentes pr-draft-summary est un framework léger et puissant pour les multiagentes pr-draft-summary ist ein leichtes und mächtiges Framework für Multiagenten O pr-draft-summary é um framework leve e poderoso para multi-agent workflows. Ele fornece uma solução eficaz para gerenciar fluxos de trabalho complexos ИИ Агенты: pr-draft-summary - легкий и мощный фреймворк для мультиагентных рабочих процессов. Он обеспечивает эффективное решение для управления сложными рабочими процессами أدوات الذكاء الاصطناعي: pr-draft-summary هو إطار عمل خفيف وقوي لتدفقات العمل المتعددة. يقدم حلًا فعالًا لدارة تدفقات العمل المعقدة A lightweight, powerful framework for multi-agent workflows AI智能代理 pr-draft-summary框架 多智能体工作流 如何使用pr-draft-summary pr-draft-summary安装 pr-draft-summary设置指南 pr-draft-summary替代品 pr-draft-summary vs 其他框架 A lightweight, powerful framework for multi-agent workflows');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('storyblok/monoblok/review-and-qa', 'community', 'storyblok', 'monoblok', 'storyblok/monoblok', 'review-and-qa', 0, 0, 55, '2026-03-04T13:07:01.721Z', '2026-03-04T13:51:40.518Z', '1f162cf045b1c210d22d246554552879964daf9521a08103f6dfad436e2516dd', '{"id":"storyblok/monoblok/review-and-qa","name":"review-and-qa","description":{"zh":"Storyblok OSS代码库审查和QA AI智能工具，帮助开发者提高代码质量和开发效率","ja":"Storyblok OSSモノレポのレビューとQAに特化したAIエージェント、開発効率とコード品質の向上をサポート","ko":"Storyblok OSS 모노레포의 리뷰 및 QA를 위한 AI 에이전트, 개발 효율과 코드 품질을 높여줍니다","es":"El monorepo de Storyblok OSS utiliza herramientas de IA para review y QA, mejorando la calidad del código","fr":"Le monorepo de Storyblok OSS utilise des outils d''IA pour la revue et la QA, améliorant la qualité du code","de":"Das Storyblok-OSS-Monorepo verwendet KI-Tools für Review und QA, um die Code-Qualität zu verbessern","pt":"O monorepo Storyblok OSS é uma ferramenta de IA para review e QA. Ele ajuda a melhorar a qualidade do código e a reduzir erros","ru":"Монорепозиторий Storyblok OSS - это инструмент ИИ для проверки и контроля качества. Он помогает улучшить качество кода и уменьшить ошибки","ar":"مونوريبوزيتوري Storyblok OSS هو أداة ذكاء اصطناعي لمراجعة وضمان الجودة. يساعد على تحسين جودة الكود وتقليل الأخطاء","en":"The Storyblok OSS monorepo"},"seo":{"title":{"zh":"AI智能工具：Storyblok OSS 代码库审查和QA","ja":"AIエージェント：Storyblok OSSモノレポのレビューとQA","ko":"AI 에이전트: Storyblok OSS 모노레포 리뷰 및 QA","es":"Herramientas de IA: Review y QA para Storyblok OSS","fr":"Outils d''IA: Revue et QA pour Storyblok OSS","de":"KI-Tools: Review und QA für Storyblok OSS","pt":"Ferramentas de IA: Review e QA com Storyblok OSS","ru":"ИИ Агенты: Review и QA с Storyblok OSS","ar":"أدوات الذكاء الاصطناعي: مراجعة وضمان الجودة مع Storyblok OSS","en":"review-and-qa"},"description":{"zh":"Storyblok OSS代码库审查和QA AI智能工具，帮助开发者提高代码质量和开发效率","ja":"Storyblok OSSモノレポのレビューとQAに特化したAIエージェント、開発効率とコード品質の向上をサポート","ko":"Storyblok OSS 모노레포의 리뷰 및 QA를 위한 AI 에이전트, 개발 효율과 코드 품질을 높여줍니다","es":"El monorepo de Storyblok OSS utiliza herramientas de IA para review y QA, mejorando la calidad del código","fr":"Le monorepo de Storyblok OSS utilise des outils d''IA pour la revue et la QA, améliorant la qualité du code","de":"Das Storyblok-OSS-Monorepo verwendet KI-Tools für Review und QA, um die Code-Qualität zu verbessern","pt":"O monorepo Storyblok OSS é uma ferramenta de IA para review e QA. Ele ajuda a melhorar a qualidade do código e a reduzir erros","ru":"Монорепозиторий Storyblok OSS - это инструмент ИИ для проверки и контроля качества. Он помогает улучшить качество кода и уменьшить ошибки","ar":"مونوريبوزيتوري Storyblok OSS هو أداة ذكاء اصطناعي لمراجعة وضمان الجودة. يساعد على تحسين جودة الكود وتقليل الأخطاء","en":"The Storyblok OSS monorepo"},"definition":{"en":"The Storyblok OSS monorepo"},"features":{"zh":["代码审查和测试","代码质量检测","开发效率提升","AI驱动的代码分析","支持多种编程语言"],"ja":["コードのレビューとテスト","コード品質の検出","開発効率の向上","AI駆動のコード分析","複数のプログラミング言語をサポート"],"ko":["코드 리뷰 및 테스트","코드 품질 검사","개발 효율 향상","AI 기반의 코드 분석","다중 프로그래밍 언어 지원"],"es":["Review de código automático","Pruebas de QA integradas","Mejora de la calidad del código","Integración con Storyblok OSS","Soporte para lenguajes de programación múltiples"],"fr":["Révision de code automatique","Tests de QA intégrés","Amélioration de la qualité du code","Intégration avec Storyblok OSS","Prise en charge de plusieurs langages de programmation"],"de":["Automatisierte Code-Überprüfung","Integrierte QA-Tests","Verbesserung der Code-Qualität","Integration mit Storyblok OSS","Unterstützung für mehrere Programmiersprachen"],"pt":["Review de código automatizado","Detecção de erros e bugs","Otimização de desempenho","Integração com ferramentas de desenvolvimento","Suporte a múltiplos linguagens de programação"],"ru":["Автоматический обзор кода","Обнаружение ошибок и багов","Оптимизация производительности","Интеграция с инструментами разработки","Поддержка нескольких языков программирования"],"ar":["مراجعة الكود التلقائية","كشف الأخطاء والعيوب","تحسين الأداء","التكامل مع أدوات التطوير","دعم لغات برمجة متعددة"]},"keywords":{"zh":["如何使用Storyblok OSS","Storyblok OSS代码库审查","AI智能工具","代码质量检测","开发效率提升","Storyblok OSS替代品","Storyblok OSS安装"],"ja":["Storyblok OSSの使い方","Storyblok OSSモノレポのレビュー","AIエージェント","コード品質の検出","開発効率の向上","Storyblok OSSの代替","Storyblok OSSのインストール"],"ko":["Storyblok OSS 사용법","Storyblok OSS 모노레포 리뷰","AI 에이전트","코드 품질 검사","개발 효율 향상","Storyblok OSS 대체","Storyblok OSS 설치 가이드"],"es":["cómo utilizar herramientas de IA","herramientas de IA para review de código","Storyblok OSS alternativa","instalación de herramientas de IA","guía de configuración de herramientas de IA","mejora de la calidad del código con IA"],"fr":["comment utiliser les outils d''IA","outils d''IA pour la revue de code","Storyblok OSS alternative","installation des outils d''IA","guide de configuration des outils d''IA","amélioration de la qualité du code avec l''IA"],"de":["wie man KI-Tools verwendet","KI-Tools für Code-Überprüfung","Storyblok OSS Alternative","Installation von KI-Tools","Konfigurationsleitfaden für KI-Tools","Verbesserung der Code-Qualität mit KI"],"pt":["ferramentas de ia","review de código","qa automatizado","storyblok oss","desenvolvimento de software","otimização de desempenho","integração com ferramentas de desenvolvimento"],"ru":["ии агенты","обзор кода","автоматизированный контроль качества","storyblok oss","разработка программного обеспечения","оптимизация производительности","интеграция с инструментами разработки"],"ar":["أدوات الذكاء الاصطناعي","مراجعة الكود","ضمان الجودة التلقائي","storyblok oss","تطوير البرمجيات","تحسين الأداء","التكامل مع أدوات التطوير"]}},"owner":"storyblok","repo":"monoblok","repoPath":"storyblok/monoblok","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.721Z","topics":[],"category":"community","skillMd":{"name":"review-and-qa","description":"Review the changes for <commit|branch|pr> and create a QA review plan","bodyPreview":"# Review Changes\n\nReview the changes for: $ARGUMENTS.\n\n## Instructions\n\nPerform a two-phase review:\n\n1. **Code review** - Review quality, architecture, and best practices.\n2. **QA review** - Create manual test cases to validate behavior.\n\n## Phase 1: Code review\n\nAnalyze the code changes for:\n\n## PR checklist\n\n### Required for all PRs\n\n- [ ] **Small diff** - One logical change. If the PR does multiple things, split it.\n- [ ] **Tests included** - New functionality has tests. Bug fixes have regres","body":"# Review Changes\n\nReview the changes for: $ARGUMENTS.\n\n## Instructions\n\nPerform a two-phase review:\n\n1. **Code review** - Review quality, architecture, and best practices.\n2. **QA review** - Create manual test cases to validate behavior.\n\n## Phase 1: Code review\n\nAnalyze the code changes for:\n\n## PR checklist\n\n### Required for all PRs\n\n- [ ] **Small diff** - One logical change. If the PR does multiple things, split it.\n- [ ] **Tests included** - New functionality has tests. Bug fixes have regression tests.\n- [ ] **No secrets** - No tokens, passwords, or credentials in the code.\n\n### If user-facing changes\n\n- [ ] **Docs updated** - The README or relevant documentation reflects the change.\n- [ ] **Examples work** - Code examples in the documentation are tested and copy-paste ready.\n- [ ] **Error messages helpful** - New errors explain what went wrong and how to fix it.\n\n### If breaking changes\n\n- [ ] **Migration notes** - Provide clear before and after examples showing how to upgrade.\n- [ ] **Changelog entry** - Follow conventional commits for release notes.\n- [ ] **Deprecation warnings** - If keeping an old API temporarily, warn users.\n\n### If adding dependencies\n\n- [ ] **Justified** - No existing solution exists in the codebase.\n- [ ] **License compatible** - Use MIT or a compatible license.\n- [ ] **Maintained** - Use an active project with recent updates.\n- [ ] **Size reasonable** - Avoid adding significant bundle weight.\n\n### Quality and clean code\n\n- [ ] Functions are small and single-purpose.\n- [ ] Variable and function names are descriptive.\n- [ ] No dead code or commented-out blocks exist.\n- [ ] No magic numbers exist (use constants).\n- [ ] Error messages are helpful.\n\n### Architecture and design\n\n- [ ] Changes fit existing patterns in the codebase.\n- [ ] No unnecessary coupling exists between modules.\n- [ ] Proper separation of concerns exists (actions vs. commands vs. utils).\n- [ ] Types and interfaces are defined appropriately.\n\n### Reusability and centralization\n\n- [ ] Duplicated logic is extracted to shared utilities.\n- [ ] Existing helpers are used where applicable.\n- [ ] New utilities are generic enough for reuse.\n- [ ] Constants are centralized (not scattered).\n\n### Best practices\n\n- [ ] Async and await are used consistently (no mixed patterns).\n- [ ] Errors are propagated correctly (not swallowed).\n- [ ] Edge cases are handled (null, empty, invalid input).\n- [ ] No security issues exist (injection, secrets exposure).\n\n### Output format (code review)\n\n```markdown\n## Code review summary\n\n[LGTM / Needs changes / Blocking issues]\n\n## Issues found\n\n### [Critical/Major/Minor]: Issue title\n\n**File:** `path/to/file.ts:123`\n**Problem:** Description.\n**Suggestion:** How to fix.\n```\n\n## Phase 2: QA review\n\n### Test case structure\n\nRefer to the [Test Plan Template](./templates/test-plan.md) and the [Test Plan Example](./examples/assets-test-plan.md) for test plan structure guidance.\n\n### Coverage requirements\n\nCreate test cases for:\n\n1. **Happy path** - Normal successful operation.\n2. **Negative cases** - Invalid input, unauthorized access, and missing data.\n3. **Edge cases** - Empty input, large input, and special characters.\n4. **Error recovery** - What happens when things fail mid-operation.\n"},"lastSynced":"2026-03-04T13:51:40.518Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents requiring meticulous analysis of pull requests and adherence to best practices.","zh":"适合需要仔细分析拉取请求和遵循最佳实践的代码审查代理。","ja":"プルリクエストの厳密な分析とベストプラクティスの遵守を必要とするコードレビューエージェントに最適。","ko":"풀 요청과 최선의 관행을 신중하게 분석해야 하는 코드 검토 에이전트에 적합합니다.","es":"Ideal para Agentes de Revisión de Código que requieren un análisis meticuloso de solicitudes de incorporación y el cumplimiento de las mejores prácticas.","fr":"Idéal pour les Agents de Revue de Code nécessitant une analyse minutieuse des demandes d''intégration et le respect des meilleures pratiques.","de":"Ideal für Code-Review-Agents, die eine gründliche Analyse von Pull-Requests und die Einhaltung von Best Practices erfordern.","pt":"Ideal para Agentes de Revisão de Código que exigem análise meticulosa de pull requests e aderência às melhores práticas.","ru":"Идеально для агентов проверки кода, требующих тщательного анализа запросов на включение и соблюдения лучших практик.","ar":"مثالي لعميل مراجعة الشفرة الذي يتطلب تحليلاً دقيقاً لطلبات السحب والامتثال لأفضل الممارسات."},"recommendation":{"en":"Empowers agents to scrutinize code quality, architecture, and test coverage, ensuring compliance with PR checklists and validating behavior through manual test cases, utilizing protocols like GitHub PR reviews and file formats such as Markdown for documentation.","zh":"赋予代理审查代码质量、架构和测试覆盖率，确保遵守PR检查清单，并通过手动测试用例验证行为，利用GitHub PR审查等协议和Markdown等文件格式进行文档编制。","ja":"エージェントがコードの品質、構造、テストカバレッジを検証し、PRチェックリストの遵守を確保し、手動テストケースを介して動作を検証することを可能にし、GitHub PRレビューなどのプロトコルやMarkdownなどのファイル形式を使用してドキュメント化を行います。","ko":"에이전트가 코드 품질, 구조 및 테스트 커버리지에 대한 철저한 분석을 수행할 수 있도록 해주며, PR 체크 목록 준수 및 수동 테스트 케이스를 통한 동작 검증을 통해 GitHub PR 리뷰와 같은 프로토콜 및 Markdown과 같은 파일 형식을 사용하여 문서화 합니다.","es":"Habilita a los agentes a examinar la calidad del código, la arquitectura y la cobertura de pruebas, garantizando el cumplimiento de las listas de verificación de PR y validando el comportamiento a través de casos de prueba manuales, utilizando protocolos como las revisiones de PR de GitHub y formatos de archivo como Markdown para la documentación.","fr":"Permet aux agents d''examiner la qualité du code, l''architecture et la couverture de tests, en garantissant la conformité aux listes de vérification de PR et en validant le comportement par le biais de cas de tests manuels, en utilisant des protocoles tels que les révisions de PR de GitHub et des formats de fichiers tels que Markdown pour la documentation.","de":"Ermächtigt die Agenten, die Codequalität, Architektur und Testabdeckung zu überprüfen, die Einhaltung der PR-Checklisten sicherzustellen und das Verhalten durch manuelle Testfälle zu validieren, unter Verwendung von Protokollen wie GitHub-PR-Reviews und Dateiformaten wie Markdown für die Dokumentation.","pt":"Habilita os agentes a examinar a qualidade do código, arquitetura e cobertura de testes, garantindo o cumprimento das listas de verificação de PR e validando o comportamento por meio de casos de teste manuais, utilizando protocolos como revisões de PR do GitHub e formatos de arquivo como Markdown para documentação.","ru":"Наделяет агентов возможностью проверять качество кода, архитектуру и покрытие тестами, обеспечивая соблюдение контрольных списков PR и проверку поведения с помощью ручных тестовых случаев, используя протоколы, такие как обзоры PR GitHub, и форматы файлов, такие как Markdown, для документации.","ar":"يتمكن العملاء من فحص جودة الشفرة والهياكل والغطاء التجريبي، وضمان الامتثال لقوائم مراجعة الطلبات والتحقق من السلوك من خلال حالات اختبار يدوية، باستخدام بروتوكولات مثل مراجعات طلبات السحب من جيت هاب وتنسيقات الملفات مثل ماركداون للتوثيق."},"useCases":{"en":["Automating code reviews for monorepo projects like Storyblok OSS","Generating test cases for new functionality and bug fixes","Validating pull request compliance with required checklists"],"zh":["自动化Storyblok OSS等单体仓库项目的代码审查","为新功能和bug修复生成测试用例","验证拉取请求是否遵守所需的检查清单"],"ja":["Storyblok OSSなどのモノレポプロジェクトのコードレビューを自動化する","新しい機能やバグフィックスのテストケースを生成する","プルリクエストが必要なチェックリストに準拠していることを検証する"],"ko":["Storyblok OSS 등의 모노레포 프로젝트를 위한 코드 리뷰 자동화","새로운 기능 및 버그 수정을 위한 테스트 케이스 생성","필요한 체크 목록을 준수하는 풀 리퀘스트 유효성 검사"],"es":["Automatización de revisiones de código para proyectos monorepo como Storyblok OSS","Generación de casos de prueba para nueva funcionalidad y correcciones de errores","Validación del cumplimiento de las solicitudes de incorporación con las listas de verificación requeridas"],"fr":["Automatisation des revues de code pour les projets monorepo comme Storyblok OSS","Génération de cas de tests pour les nouvelles fonctionnalités et les corrections de bogues","Validation du respect des demandes d''intégration avec les listes de vérification requises"],"de":["Automatisierung von Code-Reviews für Monorepo-Projekte wie Storyblok OSS","Generierung von Testfällen für neue Funktionalitäten und Fehlerkorrekturen","Validierung der Einhaltung von Pull-Requests mit den erforderlichen Checklisten"],"pt":["Automatizar revisões de código para projetos monorepo como Storyblok OSS","Gerar casos de teste para novas funcionalidades e correções de bugs","Validar o cumprimento do pull request com as listas de verificação necessárias"],"ru":["Автоматизировать проверку кода для монорепозиториев, таких как Storyblok OSS","Генерировать тестовые случаи для новых функций и исправлений ошибок","Проверять соблюдение запросов на включение требуемых контрольных списков"],"ar":["أتمتة مراجعة الشفرة لمشاريع مونوريبو مثل ستوريبلوك أو إس إس","توليد حالات اختبار للوظائف الجديدة وتصحيح الأخطاء","التحقق من امتثال طلبات السحب للقوائم المراجعة المطلوبة"]},"limitations":{"en":["Requires access to version control systems like GitHub","Limited to code review and QA, not suited for full-stack development or deployment"],"zh":["需要访问GitHub等版本控制系统","仅限代码审查和QA，不适合全栈开发或部署"],"ja":["GitHubなどのバージョン管理システムへのアクセスが必要","コードレビューとQAのみに限定されており、フルスタック開発やデプロイには適していない"],"ko":["GitHub 등의 버전 관리 시스템에 대한 액세스가 필요함","코드 리뷰 및 QA에만 국한되며, 풀 스택 개발 또는 배포에는 적합하지 않음"],"es":["Requiere acceso a sistemas de control de versiones como GitHub","Limitado a la revisión de código y QA, no adecuado para el desarrollo o la implementación de full-stack"],"fr":["Nécessite un accès aux systèmes de contrôle de version tels que GitHub","Limité à la revue de code et à la QA, non adapté au développement ou au déploiement full-stack"],"de":["Erfordert den Zugriff auf Versionskontrollsysteme wie GitHub","Begrenzt auf Code-Review und QA, nicht geeignet für die volle Entwicklung oder Bereitstellung"],"pt":["Exige acesso a sistemas de controle de versão como o GitHub","Limitado à revisão de código e QA, não é adequado para desenvolvimento ou implantação de pilha completa"],"ru":["Требует доступа к системам контроля версий, таким как GitHub","Ограничен проверкой кода и QA, не подходит для полноценного развития или развертывания"],"ar":["يتطلب الوصول إلى أنظمة التحكم في الإصدار مثل جيت هاب","محدود لمراجعة الشفرة وتحقق الجودة، وليس مناسبًا لتطوير أو نشر الكل"]},"version":3},"contentHash":"1f162cf045b1c210d22d246554552879964daf9521a08103f6dfad436e2516dd","qualityScore":55}');
