INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Dexploarer/hyper-forge/api-gateway-configurator', 'api-gateway-configurator', 'Dexploarer', 'hyper-forge', 'community', 'api-gateway-configurator Dexploarer hyper-forge community AI智能配置API网关是游戏开发中的一个强大工具，能够简化API网关的设置和管理 AIエージェントによるAPIゲートウェイ設定は、ゲーム開発者がAPIゲートウェイを簡単に設定できるようにするためのプラットフォームです AI 에이전트를 사용한 API 게이트웨이 구성은 게임 개발자들이 API 게이트웨이를 쉽게 설정하고 관리할 수 있는 플랫폼입니다 Nuestra plataforma de generación de activos 3D impulsada por IA permite a los desarrolladores de juegos crear activos de manera rápida y eficiente. Configuración de API Gateway incluida Notre plateforme de génération d''actifs 3D propulsée par l''IA permet aux développeurs de jeux de créer des actifs de manière rapide et efficace. Configuration de la passerelle API incluse Unsere 3D-Asset-Generierungsplattform für Spielentwicklung, angetrieben von KI, ermöglicht es Entwicklern, Assets schnell und effizient zu erstellen. API-Gateway-Konfiguration inklusive A plataforma de geração de ativos 3D por IA para desenvolvimento de jogos, com configurador de gateway de API para melhorar a produtividade do time de desenvolvimento Платформа генерации 3D-активов ИИ для разработки игр, с конфигуратором API-шлюза для повышения производительности команды разработчиков منصة إنشاء موارد ثلاثية الأبعاد بالذكاء الاصطناعي لتطوير الألعاب، مع مكوّن بوابة واجهة برمجة التطبيقات لتحسين إنتاجية فريق التطوير AI-powered 3D asset generation platform for game development 如何使用AI配置API网关 API网关配置工具 AI智能API网关设置 游戏开发API网关 API网关设置教程 API网关安全性 API网关性能优化 AI-powered 3D asset generation platform for game development');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jaredlander/freshbooks-speed/javascript-ember', 'community', 'jaredlander', 'freshbooks-speed', 'jaredlander/freshbooks-speed', 'javascript-ember', 0, 0, 55, '2026-03-04T13:07:01.769Z', '2026-03-04T14:20:19.716Z', '00453b246993ecf8d2975b16c4efc3e2ed9b87d326acd01a53104d73d4412494', '{"id":"jaredlander/freshbooks-speed/javascript-ember","name":"javascript-ember","description":{"zh":"javascript-ember是一个Chrome扩展程序，用于解决Freshbooks网站的速度问题，提高开发者效率","ja":"javascript-emberは、Freshbooksウェブサイトの速度問題を解決し、開発者の効率を向上させるChrome拡張機能です","ko":"javascript-ember는 Freshbooks 웹사이트의 속도 문제를 해결하여 개발자 효율성을 향상시키는 Chrome 확장 프로그램입니다","es":"La extensión de Chrome para Javascript Ember soluciona problemas de velocidad en Freshbooks, mejorando la experiencia del usuario.","fr":"L''extension Chrome pour Javascript Ember résout les problèmes de vitesse sur Freshbooks, améliorant l''expérience utilisateur.","de":"Die Chrome-Erweiterung für Javascript Ember löst Geschwindigkeitsprobleme in Freshbooks und verbessert die Benutzererfahrung.","pt":"Nossa extensão de Chrome em JavaScript resolve problemas de velocidade no site Freshbooks.","ru":"Наше расширение Chrome на JavaScript решает проблемы с скоростью на сайте Freshbooks.","ar":"إمتدادنا على Chrome مكتوب بلغة JavaScript يحل مشاكل السرعة على موقع Freshbooks.","en":"A Chrome extension to fix speed issues in the Freshbooks website"},"seo":{"title":{"zh":"AI智能工具：javascript-ember Freshbooks加速","ja":"AIエージェント：javascript-ember Freshbooks高速化","ko":"AI 에이전트: javascript-ember Freshbooks 속도 개선","es":"Herramientas de AI: Extensión de Chrome para optimizar Fr...","fr":"Outils d''IA: Extension Chrome pour accélérer Freshbooks a...","de":"KI-Tools: Chrome-Erweiterung für die Optimierung von Fres...","pt":"Ferramenta de Otimização de Velocidade para Freshbooks em...","ru":"ИИ Агент для оптимизации скорости Freshbooks на JavaScript","ar":"أداة تحسين السرعة لموقع Freshbooks باستخدام JavaScript","en":"javascript-ember"},"description":{"zh":"javascript-ember是一个Chrome扩展程序，用于解决Freshbooks网站的速度问题，提高开发者效率","ja":"javascript-emberは、Freshbooksウェブサイトの速度問題を解決し、開発者の効率を向上させるChrome拡張機能です","ko":"javascript-ember는 Freshbooks 웹사이트의 속도 문제를 해결하여 개발자 효율성을 향상시키는 Chrome 확장 프로그램입니다","es":"La extensión de Chrome para Javascript Ember soluciona problemas de velocidad en Freshbooks, mejorando la experiencia del usuario.","fr":"L''extension Chrome pour Javascript Ember résout les problèmes de vitesse sur Freshbooks, améliorant l''expérience utilisateur.","de":"Die Chrome-Erweiterung für Javascript Ember löst Geschwindigkeitsprobleme in Freshbooks und verbessert die Benutzererfahrung.","pt":"Nossa extensão de Chrome em JavaScript resolve problemas de velocidade no site Freshbooks.","ru":"Наше расширение Chrome на JavaScript решает проблемы с скоростью на сайте Freshbooks.","ar":"إمتدادنا على Chrome مكتوب بلغة JavaScript يحل مشاكل السرعة على موقع Freshbooks.","en":"A Chrome extension to fix speed issues in the Freshbooks website"},"definition":{"en":"A Chrome extension to fix speed issues in the Freshbooks website"},"features":{"zh":["解决Freshbooks速度问题","提高开发者效率","支持Chrome浏览器","易于安装和使用","免费使用"],"ja":["Freshbooksの速度問題を解決","開発者の効率を向上させる","Chromeブラウザをサポート","簡単にインストールして使用","無料で使用"],"ko":["Freshbooks 속도 문제 해결","개발자 효율성 향상","Chrome 브라우저 지원","설치 및 사용이 쉬움","무료 사용"],"es":["Optimización de velocidad en Freshbooks","Extensión de Chrome basada en Javascript Ember","Mejora de la experiencia del usuario","Solución de problemas de rendimiento","Implementación sencilla"],"fr":["Amélioration de la vitesse sur Freshbooks","Extension Chrome basée sur Javascript Ember","Amélioration de l''expérience utilisateur","Résolution de problèmes de performances","Mise en œuvre simplifiée"],"de":["Geschwindigkeitsoptimierung in Freshbooks","Chrome-Erweiterung auf Basis von Javascript Ember","Verbesserung der Benutzererfahrung","Lös