INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('legasicrypto/skale-hackathon/x402', 'x402', 'legasicrypto', 'skale-hackathon', 'community', 'x402 legasicrypto skale-hackathon community SKALE x402 AI智能工具是Legasi Hackathon的EVM端口，提供了新的开发可能性 SKALE x402 AIエージェントはLegasiハッカソンのEVMポートであり、新しい開発の可能性を提供します SKALE x402 AI 에이전트는 Legasi 해커톤의 EVM 포트로서 새로운 개발 가능성을 제공합니다 Legasi es un hackathon SKALE x402 que ofrece un entorno de desarrollo de contratos inteligentes con EVM port. Legasi est un hackathon SKALE x402 qui propose un environnement de développement de contrats intelligents avec port EVM. Legasi ist ein SKALE x402 Hackathon, der eine Entwicklungsumgebung für Smart Contracts mit EVM-Port bietet. O x402 é uma ferramenta de IA para desenvolvedores, criada durante o Legasi SKALE Hackathon, com foco em EVM port. x402 - это инструмент ИИ для разработчиков, созданный во время хакатона Legasi SKALE, с упором на EVM port. x402 هو أداة الإي أй للمطورين، تم إنشاؤها خلال هاكاثون Legasi SKALE، مع التركيز على منفذ EVM. Legasi — SKALE x402 Hackathon (EVM port) SKALE x402 AI智能工具 Legasi Hackathon EVM端口 AI智能工具开发 SKALE x402 安装 SKALE x402 教程 AI智能工具比较 SKALE x402 vs 其他AI工具 Legasi — SKALE x402 Hackathon (EVM port)');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('quests-org/quests/changelog', 'community', 'quests-org', 'quests', 'quests-org/quests', 'changelog', 0, 0, 55, '2026-03-04T13:07:01.795Z', '2026-03-04T14:27:54.000Z', '47d2a62152e7f8eecd66bdfd5bd0221ba8553ea072cf32224e49dd3c0ca53922', '{"id":"quests-org/quests/changelog","name":"changelog","description":{"zh":"Changelog是开源应用构建器，用于快速打造定制化应用。基于Node.js和React，提供CLI工具和Agent集成","ja":"Changelogはオープンソースアプリビルダーで、カスタマイズされたアプリを迅速に構築する。Node.jsとReactをベースにし、CLIツールとAgentの統合を提供する","ko":"Changelog는 오픈소스 앱 빌더로 커스터마이즈된 앱을 빠르게 구축합니다. Node.js와 React를 기반으로 하며 CLI 툴과 에이전트 통합을 제공합니다","es":"El agent de cambio es una herramienta que permite gestionar los cambios en tus aplicaciones de manera efectiva.","fr":"L''agent de changelog est une outil qui permet de gérer les changements dans vos applications de manière efficace.","de":"Der Agent für Änderungen in Anwendungen ist ein Tool, das es ermöglicht, die Änderungen in Ihren Anwendungen effektiv zu verwalten.","pt":"O Changelog é uma ferramenta de código aberto para construir aplicativos. Ele oferece recursos para desenvolvedores que trabalham com React, Python e Node.js","ru":"Changelog - открытый конструктор приложений. Он предоставляет функции для разработчиков, работающих с React, Python и Node.js","ar":"شروط التغيير المفتوح هو أداة مفتوحة المصدر لبناء التطبيقات. إنه يوفر ميزات لمطوري التطبيقات الذين يعملون مع React و Python و Node.js","en":"The open-source app builder"},"seo":{"title":{"zh":"AI智能工具：开源应用构建器Changelog","ja":"AIエージェント：オープンソースアプリビルダーChangelog","ko":"AI 에이전트: 오픈소스 앱 빌더 Changelog","es":"Agent de cambio para aplicaciones","fr":"Agent de changelog pour applications","de":"Agent für Änderungen in Anwendungen","pt":"Ferramentas de IA: Conheça o Changelog","ru":"ИИ Агенты: Changelog - открытый конструктор приложений","ar":"أدوات الذكاء الاصطناعي: شروط التغيير المفتوح","en":"changelog"},"description":{"zh":"Changelog是开源应用构建器，用于快速打造定制化应用。基于Node.js和React，提供CLI工具和Agent集成","ja":"Changelogはオープンソースアプリビルダーで、カスタマイズされたアプリを迅速に構築する。Node.jsとReactをベースにし、CLIツールとAgentの統合を提供する","ko":"Changelog는 오픈소스 앱 빌더로 커스터마이즈된 앱을 빠르게 구축합니다. Node.js와 React를 기반으로 하며 CLI 툴과 에이전트 통합을 제공합니다","es":"El agent de cambio es una herramienta que permite gestionar los cambios en tus aplicaciones de manera efectiva.","fr":"L''agent de changelog est une outil qui permet de gérer les changements dans vos applications de manière efficace.","de":"Der Agent für Änderungen in Anwendungen ist ein Tool, das es ermöglicht, die Änderungen in Ihren Anwendungen effektiv zu verwalten.","pt":"O Changelog é uma ferramenta de código aberto para construir aplicativos. Ele oferece recursos para desenvolvedores que trabalham com React, Python e Node.js","ru":"Changelog - открытый конструктор приложений. Он предоставляет функции для разработчиков, работающих с React, Python и Node.js","ar":"شروط التغيير المفتوح هو أداة مفتوحة المصدر لبناء التطبيقات. إنه يوفر ميزات لمطوري التطبيقات الذين يعملون مع React و Python و Node.js","en":"The open-source app builder"},"definition":{"en":"The open-source app builder"},"features":{"zh":["基于Node.js和React","提供CLI工具","Agent集成","快速构建定制化应用","开源和可扩展"],"ja":["Node.jsとReactをベースに","CLIツールを提供","Agentの統合","カスタマイズされたアプリを迅速に構築","オープンソースで拡張可能"],"ko":["Node.js와 React를 기반으로","CLI 툴 제공","에이전트 통합","커스터마이즈된 앱을 빠르게 구축","오픈소스이고 확장 가능"],"es":["Gestión de cambios en aplicaciones","Gestión de versiones de aplicaciones","Gestión de dependencias de aplicaciones"],"fr":["Gestion des changements dans les applications","Gestion des versions d''applications","Gestion des dépendances d''applications"],"de":["Gestión de cambios en Anwendungen","Gestión de versiones de Anwendungen","Gestión de dependencias de Anwendungen"],"pt":["Construção de aplicativos com React","Desenvolvimento com Python e Node.js","Recursos de código aberto","Fácil integração com CLI","Suporte a desenvolvedores"],"ru":["Разработка приложений с использованием React","Разработка с использованием Python и Node.js","Функции открытого кода","Легкая интеграция с CLI","Поддержка разработчиков"],"ar":["بناء التطبيقات باستخدام React","التطوير باستخدام Python و Node.js","ميزات مفتوحة المصدر","إضافة سهلة مع CLI","دعم المطورين"]},"keywords":{"zh":["如何使用Changelog","什么是开源应用构建器","Changelog替代品","Changelog vs 其他工具","Changelog安装","Changelog设置指南","AI智能工具","应用构建器"],"ja":["Changelogの使い方","オープンソースアプリビルダーの定義","Changelogの代替","Changelog vs 他のツール","Changelogのインストール","Changelogの設定ガイド","AIエージェント","アプリビルダー"],"ko":["Changelog 사용법","오픈소스 앱 빌더 정의","Changelog 대체품","Changelog vs 다른 툴","Changelog 설치","Changelog 설정 가이드","AI 에이전트","앱 빌더"],"es":["agent de cambio","gestión de cambios en aplicaciones","gestión de versiones de aplicaciones","gestión de dependencias de aplicaciones","how to use agent de cambio","what is agent de cambio"],"fr":["agent de changelog","gestion des changements dans les applications","gestion des versions d''applications","gestion des dépendances d''applications","how to use agent de changelog","what is agent de changelog"],"de":["agent für änderungen in anwendungen","gestión de cambios en anwendungen","gestión de versiones de anwendungen","gestión de dependencias de anwendungen","how to use agent für änderungen in anwendungen","what is agent für änderungen in anwendungen"],"pt":["como usar Changelog","o que é Changelog","Changelog alternativa","Changelog vs outros construtores","instalar Changelog","guia de configuração do Changelog","desenvolvimento de aplicativos com React","desenvolvimento com Python e Node.js"],"ru":["как использовать Changelog","что такое Changelog","Changelog альтернатива","Changelog vs другие конструкторы","установить Changelog","руководство по настройке Changelog","разработка приложений с использованием React","разработка с использованием Python и Node.js"],"ar":["كيفية استخدام شروط التغيير المفتوح","ما هو شروط التغيير المفتوح","بديل شروط التغيير المفتوح","شروط التغيير المفتوح مقابل منشئين آخرين","تثبيت شروط التغيير المفتوح","دليل إعداد شروط التغيير المفتوح","بناء التطبيقات باستخدام React","التطوير باستخدام Python و Node.js"]}},"owner":"quests-org","repo":"quests","repoPath":"quests-org/quests","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.795Z","topics":[],"category":"community","skillMd":{"name":"changelog","description":"Generate changelog from git commits","bodyPreview":"## Approach\n\n1. Use `git` to look for the most recent tagged non-beta version.\n2. If the most recent commit doesn''t have a tag, use it as the current version.\n3. Find the previous version.\n4. Inspect the content of any larger commits.\n5. Generate a change log for that based on the style of a few of these example change logs down below.\n6. Return the results in a markdown code block.\n\n## Guidelines\n\n- Don''t include verbatim commit messages.\n- Write copy for a general audience.\n- Only include the","body":"## Approach\n\n1. Use `git` to look for the most recent tagged non-beta version.\n2. If the most recent commit doesn''t have a tag, use it as the current version.\n3. Find the previous version.\n4. Inspect the content of any larger commits.\n5. Generate a change log for that based on the style of a few of these example change logs down below.\n6. Return the results in a markdown code block.\n\n## Guidelines\n\n- Don''t include verbatim commit messages.\n- Write copy for a general audience.\n- Only include the \"Features\" and \"Bug Fixes\" sections.\n\n## Example 1\n\n```markdown\n## Features\n\n- **Chat mode** has landed! Switch between building apps and chatting with the agent.\n- **Projects page** with table view - delete, stop, and manage all your projects in one place.\n- Recent projects displayed on new tab.\n- Copy button for pre blocks in Markdown.\n- Use new projects page for eval viewing.\n- Incorporate upstream error messages for multiple matches.\n\n## Bug Fixes\n\n- Full width assistant messages always, and copy button for single line code too.\n- Support navigation API even on root pages like not found.\n- Remove redundant app type in tab title.\n- Remove more markdown in titles.\n- Attempt to avoid race condition during project deletion due to session abort.\n- Make command/ctrl + r work everywhere unless disabled.\n- Disallow creation of session db during entire deletion process.\n- Better handle ripgrep arguments.\n- Animated stop icon in proper places.\n\n## ⛵︎\n\n_72 commits since v1.5.0_\n\nMore will follow.\n```\n\n## Example 2\n\n```markdown\n## 🧬 Features\n\n- Evals have landed!\n- A couple clicks and you can compare rich output from as many models and apps you desire.\n- Built-in prompts for standard eval apps and some goofy ones too.\n- Suport fo custom eval prompts.\n- Dedicated runs page with bulk actions.\n\n## 🩹 Bug Fixes\n\n- Linux: Fixed DBus safe storage issues by setting up direct DBus communication.\n- Workspace: Ensured runtime starts when agent session spawns to prevent missing dependencies.\n- AI Gateway: Fixed handling of `:latest` style model names (e.g., `gpt-oss:latest`).\n- Workspace: Blocked `pnpm dev`, `pnpm start`, and `pnpm run` variants since Quests already manages app lifecycle.\n\n## Water Vehicle\n\n<!-- Image placeholder -->\n\n_23 commits since v1.4.2_\n```\n"},"lastSynced":"2026-03-04T14:27:54.000Z","agentAnalysis":{"suitability":{"en":"Perfect for Version Control Agents needing automated changelog generation using git.","zh":"非常适合需要使用 git 自动生成变更日志的版本控制代理。","ja":"git を使用して自動的に変更ログを生成する必要があるバージョン管理エージェントに最適です。","ko":"git를 사용하여 자동으로 변경 로그를 생성해야 하는 버전 제어 에이전트에 적합합니다.","es":"Perfecto para Agentes de Control de Versiones que necesitan generación automática de registros de cambios utilizando git.","fr":"Parfait pour les Agents de Contrôle de Version nécessitant une génération automatisée de journaux des modifications à l''aide de git.","de":"Perfekt für Versionskontrollagenten, die eine automatisierte Erstellung von Änderungsprotokollen mit git benötigen.","pt":"Perfeito para Agentes de Controle de Versão que precisam de geração automática de registros de alterações usando git.","ru":"Идеально подходит для агентов контроля версий, которым требуется автоматизированная генерация журнала изменений с помощью git.","ar":"مثالي للوكلاء إدارة الإصدار الذين يحتاجون إلى توليد تلقائي لسجل التغييرات باستخدام git."},"recommendation":{"en":"Empowers agents to generate human-readable changelogs from git commits, using markdown formatting and excluding verbatim commit messages, while supporting tagged non-beta versions and inspecting larger commits for relevant changes.","zh":"使代理能够从 git 提交中生成人类可读的更改日志，使用 markdown 格式，并排除逐字的提交消息，同时支持标记的非 beta 版本，并检查较大的提交以查找相关更改。","ja":"エージェントが git コミットから人間が読みやすい変更ログを生成できるようにし、markdown 形式を使用し、逐語的コミット メッセージを除外し、タグ付けされた非 beta バージョンをサポートし、大きなコミットを検査して関連する変更を探します。","ko":"에이전트가 git 커밋에서 인간이 읽을 수 있는 변경 로그를 생성할 수 있도록 하며, markdown 형식을 사용하고,逐語的 커밋 메시지를 제외하며, 태그가 된 비 베타 버전을 지원하며, 더 큰 커밋을 검사하여 관련 변경 사항을 찾습니다.","es":"Habilita a los agentes a generar registros de cambios legibles por humanos a partir de los commits de git, utilizando formato markdown y excluyendo mensajes de commit verbatim, al mismo tiempo que admite versiones no beta etiquetadas e inspecciona commits más grandes para cambios relevantes.","fr":"Permet aux agents de générer des journaux des modifications lisibles par l''homme à partir des validations git, en utilisant un format markdown et en excluant les messages de validation verbatim, tout en prenant en charge les versions non bêta étiquetées et en inspectant les validations plus importantes pour les modifications pertinentes.","de":"Ermächtigt Agenten, menschenlesbare Änderungsprotokolle aus git-Commits zu generieren, unter Verwendung von Markdown-Formatierung und unter Ausschluss von wörtlichen Commit-Mitteilungen, während es gleichzeitig Unterstützung für getaggte Nicht-Beta-Versionen bietet und größere Commits auf relevante Änderungen untersucht.","pt":"Habilita os agentes a gerar registros de alterações legíveis por humanos a partir de confirmações git, usando formatação markdown e excluindo mensagens de confirmação literais, além de suportar versões não-beta marcadas e inspecionar confirmações maiores para alterações relevantes.","ru":"Наделяет агентов возможностью генерировать читаемые человеком журналы изменений из коммитов git, используя форматирование markdown и исключая дословные сообщения коммитов, а также поддерживает помеченные нерелизные версии и проверяет более крупные коммиты на наличие важных изменений.","ar":"يمنح الوكلاء القدرة على توليد سجلات التغييرات القابلة للقراءة بواسطة الإنسان من التزامات git، باستخدام تنسيق markdown واستبعاد رسائل الالتزام الحرفية، مع دعم الإصدارات غير بيتا الماركمة وفحص الالتزامات الأكبر للتحديثات ذات الصلة."},"useCases":{"en":["Automating changelog updates for open-source projects","Generating release notes based on git commit history","Inspecting content changes between versions"],"zh":["为开源项目自动更新更改日志","根据 git 提交历史生成发布说明","检查版本之间的内容更改"],"ja":["オープンソース プロジェクトの変更ログを自動更新する","git コミット履歴に基づいてリリースノートを生成する","バージョン間のコンテンツ変更を検査する"],"ko":["오픈소스 프로젝트의 변경 로그를 자동으로 업데이트하는 것","git 커밋 기록을 기반으로 릴리즈 노트를 생성하는 것","버전 간의 콘텐츠 변경을 검사하는 것"],"es":["Automatizar las actualizaciones del registro de cambios para proyectos de código abierto","Generar notas de lanzamiento en función del historial de commits de git","Inspeccionar los cambios de contenido entre versiones"],"fr":["Automatiser les mises à jour du journal des modifications pour les projets open source","Générer des notes de publication en fonction de l''historique des validations git","Inspecter les modifications de contenu entre les versions"],"de":["Automatisieren von Änderungsprotokoll-Aktualisierungen für Open-Source-Projekte","Erstellen von Versionshinweisen auf der Grundlage der git-Commit-Historie","Untersuchen von Inhaltsänderungen zwischen Versionen"],"pt":["Automatizar atualizações de registros de alterações para projetos de código aberto","Gerar notas de lançamento com base na história de confirmação git","Inspecionar alterações de conteúdo entre versões"],"ru":["Автоматизировать обновления журналов изменений для проектов с открытым исходным кодом","Генерировать заметки о выпуске на основе истории коммитов git","Осматривать изменения контента между версиями"],"ar":["توفير تحديثات自动ية لسجلات التغييرات لمشاريع البرمجيات مفتوحة المصدر","توليد ملاحظات الإصدار بناءً على تاريخ الالتزام git","فحص تغييرات المحتوى بين الإصدارات"]},"limitations":{"en":["Requires git repository access","Limited to tagged non-beta versions or most recent commits"],"zh":["需要 git 仓库访问权限","仅限标记的非 beta 版本或最近的提交"],"ja":["git リポジトリへのアクセス権が必要","タグ付けされた非 beta バージョンまたは最新のコミットのみ"],"ko":["git 저장소 액세스 권한이 필요","태그가 된 비 베타 버전 또는最近의 커밋만"],"es":["Requiere acceso al repositorio git","Limitado a versiones no beta etiquetadas o commits más recientes"],"fr":["Nécessite un accès au référentiel git","Limité aux versions non bêta étiquetées ou aux validations les plus récentes"],"de":["Benötigt Zugriff auf das git-Repository","Begrenzt auf getaggte Nicht-Beta-Versionen oder die neuesten Commits"],"pt":["Exige acesso ao repositório git","Limitado a versões não-beta marcadas ou commits mais recentes"],"ru":["Требует доступа к репозиторию git","Ограничен помеченными нерелизными версиями или наиболее свежими коммитами"],"ar":["يتطلب الوصول إلى مستودع git","محدود بالإصدارات غير بيتا الماركمة أو الالتزامات الأحدث"]},"version":3},"contentHash":"47d2a62152e7f8eecd66bdfd5bd0221ba8553ea072cf32224e49dd3c0ca53922","qualityScore":55}');
